-- Aprenda se Divertindo · 80 · Baralho de cartões · trilha Saúde (500 cartões)
-- Rode depois do 79-cartoes-fiscal.sql. Cole TUDO no SQL Editor e clique em Run. Pode rodar de novo sem problema.
--
-- Matérias: Enfermagem, Legislação do SUS, Medicina e Fisioterapia.
-- Português, Raciocínio Lógico, Informática, Constitucional e as demais já usam os cartões das outras trilhas.
-- Cartões numerados a partir de 2.000.002.501. O jogo baixa os novos cartões sozinho.

insert into public.cartoes (id, trilha, materia, assunto, tipo, frente, verso, explicacao)
select id, trilha, materia, assunto, tipo, frente, verso, explicacao
from jsonb_to_recordset($c$[{"id": 2000002501, "trilha": "saude", "materia": "enf", "assunto": "Exercício profissional", "tipo": "pergunta", "frente": "Qual lei regulamenta o exercício da enfermagem?", "verso": "Lei 7.498/1986, regulamentada pelo Decreto 94.406/1987.", "explicacao": ""}, {"id": 2000002502, "trilha": "saude", "materia": "enf", "assunto": "Exercício profissional", "tipo": "pergunta", "frente": "Quem exerce a enfermagem segundo a Lei 7.498/1986?", "verso": "Enfermeiro, técnico de enfermagem, auxiliar de enfermagem e parteira, respeitados os graus de habilitação.", "explicacao": "Lei 7.498/1986, art. 2º, parágrafo único."}, {"id": 2000002503, "trilha": "saude", "materia": "enf", "assunto": "Exercício profissional", "tipo": "pergunta", "frente": "Cite atividades privativas do enfermeiro.", "verso": "Consulta de enfermagem, prescrição da assistência de enfermagem, cuidados diretos a pacientes graves com risco de vida e cuidados de maior complexidade técnica que exijam conhecimentos científicos e capacidade de decisão imediata.", "explicacao": "Lei 7.498/1986, art. 11, I."}, {"id": 2000002504, "trilha": "saude", "materia": "enf", "assunto": "Exercício profissional", "tipo": "pergunta", "frente": "O enfermeiro pode prescrever medicamentos?", "verso": "Sim, como integrante da equipe de saúde, os estabelecidos em programas de saúde pública e em rotina aprovada pela instituição.", "explicacao": "Lei 7.498/1986, art. 11, II, c."}, {"id": 2000002505, "trilha": "saude", "materia": "enf", "assunto": "Exercício profissional", "tipo": "pergunta", "frente": "O técnico e o auxiliar de enfermagem podem atuar sem supervisão do enfermeiro?", "verso": "Não. Suas atividades em instituições de saúde só podem ser desempenhadas sob orientação e supervisão do enfermeiro.", "explicacao": "Lei 7.498/1986, art. 15."}, {"id": 2000002506, "trilha": "saude", "materia": "enf", "assunto": "Exercício profissional", "tipo": "pergunta", "frente": "Qual o órgão que fiscaliza o exercício profissional da enfermagem?", "verso": "O Sistema Cofen/Corens (Conselho Federal e Conselhos Regionais de Enfermagem).", "explicacao": "Lei 5.905/1973."}, {"id": 2000002507, "trilha": "saude", "materia": "enf", "assunto": "Exercício profissional", "tipo": "pergunta", "frente": "Qual o piso salarial nacional da enfermagem para o enfermeiro?", "verso": "R$ 4.750,00; o técnico recebe 70% e o auxiliar e a parteira, 50% desse valor.", "explicacao": "Lei 14.434/2022. A aplicação foi regulada pelo STF (ADI 7.222)."}, {"id": 2000002508, "trilha": "saude", "materia": "enf", "assunto": "Ética", "tipo": "pergunta", "frente": "Qual resolução aprova o Código de Ética dos Profissionais de Enfermagem vigente?", "verso": "Resolução Cofen 564/2017.", "explicacao": ""}, {"id": 2000002509, "trilha": "saude", "materia": "enf", "assunto": "Ética", "tipo": "pergunta", "frente": "Quais as penalidades do Código de Ética de Enfermagem?", "verso": "Advertência verbal, multa, censura, suspensão do exercício profissional e cassação do direito ao exercício profissional.", "explicacao": "Resolução Cofen 564/2017, art. 108."}, {"id": 2000002510, "trilha": "saude", "materia": "enf", "assunto": "Ética", "tipo": "pergunta", "frente": "O profissional de enfermagem pode recusar-se a executar prescrição em caso de erro ou ilegibilidade?", "verso": "Sim. É direito recusar-se a executar atividades que não sejam de sua competência técnica, científica, ética e legal ou que não ofereçam segurança.", "explicacao": "Cofen 564/2017. Deve-se esclarecer a dúvida com o prescritor."}, {"id": 2000002511, "trilha": "saude", "materia": "enf", "assunto": "Ética", "tipo": "pergunta", "frente": "O sigilo profissional pode ser quebrado?", "verso": "Em casos previstos em lei, por ordem judicial ou com consentimento escrito da pessoa envolvida ou de seu representante legal.", "explicacao": "Cofen 564/2017."}, {"id": 2000002512, "trilha": "saude", "materia": "enf", "assunto": "Ética", "tipo": "pergunta", "frente": "É permitido administrar medicamento sem conhecer a ação da droga e os riscos?", "verso": "Não. É proibido administrar medicamentos sem conhecer indicação, ação da droga, via, potenciais riscos.", "explicacao": "Cofen 564/2017."}, {"id": 2000002513, "trilha": "saude", "materia": "enf", "assunto": "SAE", "tipo": "pergunta", "frente": "Quais as etapas do processo de enfermagem?", "verso": "Avaliação (coleta de dados), diagnóstico de enfermagem, planejamento, implementação e evolução de enfermagem.", "explicacao": "Resolução Cofen 736/2024, que substituiu a 358/2009."}, {"id": 2000002514, "trilha": "saude", "materia": "enf", "assunto": "SAE", "tipo": "pergunta", "frente": "Quem realiza o diagnóstico e a prescrição de enfermagem?", "verso": "Privativamente o enfermeiro.", "explicacao": "Técnicos e auxiliares participam da execução, sob supervisão."}, {"id": 2000002515, "trilha": "saude", "materia": "enf", "assunto": "SAE", "tipo": "pergunta", "frente": "O que é a taxonomia NANDA-I?", "verso": "Classificação internacional de diagnósticos de enfermagem.", "explicacao": "NIC: intervenções. NOC: resultados."}, {"id": 2000002516, "trilha": "saude", "materia": "enf", "assunto": "SAE", "tipo": "pergunta", "frente": "Qual a estrutura de um diagnóstico de enfermagem real (NANDA)?", "verso": "Título, relacionado a (fatores relacionados) e evidenciado por (características definidoras).", "explicacao": "Ex.: dor aguda relacionada a agente lesivo físico, evidenciada por relato verbal."}, {"id": 2000002517, "trilha": "saude", "materia": "enf", "assunto": "SAE", "tipo": "pergunta", "frente": "Qual a teoria de enfermagem das necessidades humanas básicas no Brasil?", "verso": "A de Wanda de Aguiar Horta, baseada na hierarquia de Maslow.", "explicacao": "Necessidades psicobiológicas, psicossociais e psicoespirituais."}, {"id": 2000002518, "trilha": "saude", "materia": "enf", "assunto": "SAE", "tipo": "pergunta", "frente": "Qual a teoria de Dorothea Orem?", "verso": "Teoria do autocuidado: o enfermeiro atua quando há déficit de autocuidado.", "explicacao": "Sistemas totalmente compensatório, parcialmente compensatório e de apoio-educação."}, {"id": 2000002519, "trilha": "saude", "materia": "enf", "assunto": "SAE", "tipo": "pergunta", "frente": "O que propôs Florence Nightingale?", "verso": "Teoria ambientalista: o ambiente (ventilação, iluminação, limpeza, ruído) influencia a recuperação do paciente.", "explicacao": "Precursora da enfermagem moderna."}, {"id": 2000002520, "trilha": "saude", "materia": "enf", "assunto": "Sinais vitais", "tipo": "pergunta", "frente": "Quais os valores de referência da frequência cardíaca em adultos?", "verso": "60 a 100 batimentos por minuto.", "explicacao": "Abaixo de 60: bradicardia. Acima de 100: taquicardia."}, {"id": 2000002521, "trilha": "saude", "materia": "enf", "assunto": "Sinais vitais", "tipo": "pergunta", "frente": "Quais os valores de referência da frequência respiratória em adultos?", "verso": "12 a 20 incursões respiratórias por minuto.", "explicacao": "Bradipneia abaixo; taquipneia acima."}, {"id": 2000002522, "trilha": "saude", "materia": "enf", "assunto": "Sinais vitais", "tipo": "pergunta", "frente": "Qual a temperatura axilar normal no adulto?", "verso": "Em torno de 35,8 °C a 37,0 °C.", "explicacao": "Febre: a partir de 37,8 °C axilar (valores variam conforme a referência)."}, {"id": 2000002523, "trilha": "saude", "materia": "enf", "assunto": "Sinais vitais", "tipo": "pares", "frente": "Hipotermia x hipertermia x febre.", "verso": "Hipotermia: temperatura abaixo de 35 °C. Febre: elevação regulada pelo hipotálamo (infecção). Hipertermia: elevação não regulada, por calor excessivo ou falha da termorregulação.", "explicacao": ""}, {"id": 2000002524, "trilha": "saude", "materia": "enf", "assunto": "Sinais vitais", "tipo": "pergunta", "frente": "Quais termos descrevem alterações do ritmo respiratório?", "verso": "Dispneia (dificuldade), apneia (ausência), ortopneia (dificuldade deitado), Cheyne-Stokes (ciclos de aumento e diminuição com apneia) e Kussmaul (profunda e rápida, comum na cetoacidose).", "explicacao": ""}, {"id": 2000002525, "trilha": "saude", "materia": "enf", "assunto": "Sinais vitais", "tipo": "pergunta", "frente": "Qual a pressão arterial considerada ótima/normal em adultos?", "verso": "Abaixo de 120 x 80 mmHg.", "explicacao": "Diretriz Brasileira de Hipertensão: hipertensão a partir de 140 x 90 mmHg."}, {"id": 2000002526, "trilha": "saude", "materia": "enf", "assunto": "Sinais vitais", "tipo": "pergunta", "frente": "Que cuidados garantem a medida correta da pressão arterial?", "verso": "Paciente sentado, em repouso de 3 a 5 minutos, bexiga vazia, sem fumar ou tomar café nos 30 min anteriores, braço apoiado na altura do coração e manguito adequado.", "explicacao": ""}, {"id": 2000002527, "trilha": "saude", "materia": "enf", "assunto": "Sinais vitais", "tipo": "pergunta", "frente": "Qual a saturação de oxigênio normal em adultos sem doença pulmonar?", "verso": "Entre 95% e 100%.", "explicacao": "Em DPOC, alvo de 88% a 92%."}, {"id": 2000002528, "trilha": "saude", "materia": "enf", "assunto": "Sinais vitais", "tipo": "pergunta", "frente": "A dor é considerada qual sinal vital?", "verso": "O quinto sinal vital.", "explicacao": "Avaliada por escalas como a numérica de 0 a 10."}, {"id": 2000002529, "trilha": "saude", "materia": "enf", "assunto": "Medicamentos", "tipo": "pergunta", "frente": "Quais são os “certos” da administração de medicamentos?", "verso": "Paciente, medicamento, via, hora, dose, registro, orientação, forma, resposta e validade, entre outros (9 a 13 certos, conforme a referência).", "explicacao": ""}, {"id": 2000002530, "trilha": "saude", "materia": "enf", "assunto": "Medicamentos", "tipo": "lacuna", "frente": "Cálculo de gotejamento: gotas/min = volume (mL) ÷ (tempo em horas × ___).", "verso": "3.", "explicacao": "Microgotas/min = volume ÷ tempo em horas."}, {"id": 2000002531, "trilha": "saude", "materia": "enf", "assunto": "Medicamentos", "tipo": "pergunta", "frente": "Quantas microgotas equivalem a 1 gota?", "verso": "3 microgotas.", "explicacao": "1 mL = 20 gotas = 60 microgotas."}, {"id": 2000002532, "trilha": "saude", "materia": "enf", "assunto": "Medicamentos", "tipo": "pergunta", "frente": "Quantas gotas correm por minuto para infundir 500 mL em 8 horas?", "verso": "Cerca de 21 gotas/min.", "explicacao": "500 ÷ (8 × 3) = 20,8."}, {"id": 2000002533, "trilha": "saude", "materia": "enf", "assunto": "Medicamentos", "tipo": "pergunta", "frente": "Tem-se ampola de 500 mg em 5 mL. Quanto aspirar para 200 mg?", "verso": "2 mL.", "explicacao": "Regra de três: 500 mg — 5 mL; 200 mg — x."}, {"id": 2000002534, "trilha": "saude", "materia": "enf", "assunto": "Medicamentos", "tipo": "pergunta", "frente": "Como transformar penicilina cristalina de 5.000.000 UI diluída em 8 mL de AD?", "verso": "Fica com 10 mL (o pó acrescenta 2 mL); 500.000 UI por mL.", "explicacao": "Na de 10.000.000 UI, o pó acrescenta 4 mL."}, {"id": 2000002535, "trilha": "saude", "materia": "enf", "assunto": "Medicamentos", "tipo": "pergunta", "frente": "Como se calcula a concentração de soro glicosado a 5%?", "verso": "5 g de glicose em cada 100 mL.", "explicacao": "SG 5% 500 mL contém 25 g de glicose."}, {"id": 2000002536, "trilha": "saude", "materia": "enf", "assunto": "Medicamentos", "tipo": "pergunta", "frente": "Qual o volume máximo recomendado para injeção intramuscular no deltoide em adultos?", "verso": "Até 2 mL (alguns autores admitem 3 mL).", "explicacao": "Ventroglúteo e vasto lateral suportam volumes maiores."}, {"id": 2000002537, "trilha": "saude", "materia": "enf", "assunto": "Medicamentos", "tipo": "pergunta", "frente": "Qual o ângulo da injeção intradérmica e um exemplo de uso?", "verso": "10 a 15 graus; usada na vacina BCG e no teste tuberculínico (PPD).", "explicacao": "Volume máximo de 0,5 mL."}, {"id": 2000002538, "trilha": "saude", "materia": "enf", "assunto": "Medicamentos", "tipo": "pergunta", "frente": "Qual o ângulo da injeção subcutânea?", "verso": "45° ou 90°, conforme o tecido subcutâneo e o tamanho da agulha.", "explicacao": "Ex.: insulina e heparina."}, {"id": 2000002539, "trilha": "saude", "materia": "enf", "assunto": "Medicamentos", "tipo": "pergunta", "frente": "Qual o local de escolha para IM que é mais seguro por estar livre de grandes vasos e nervos?", "verso": "A região ventroglútea (de Hochstetter).", "explicacao": ""}, {"id": 2000002540, "trilha": "saude", "materia": "enf", "assunto": "Medicamentos", "tipo": "pergunta", "frente": "Por que não se massageia o local após aplicar heparina subcutânea?", "verso": "Para não provocar hematomas.", "explicacao": ""}, {"id": 2000002541, "trilha": "saude", "materia": "enf", "assunto": "Medicamentos", "tipo": "pergunta", "frente": "Qual a técnica em Z e quando se usa?", "verso": "Tracionar a pele lateralmente antes de aplicar a injeção IM e soltar depois; evita refluxo de medicamentos irritantes ou que mancham a pele.", "explicacao": "Ex.: ferro intramuscular."}, {"id": 2000002542, "trilha": "saude", "materia": "enf", "assunto": "Medicamentos", "tipo": "pergunta", "frente": "O que são medicamentos de alta vigilância (potencialmente perigosos)?", "verso": "Medicamentos com maior risco de dano grave quando há erro, como insulina, heparina, cloreto de potássio concentrado, opioides e quimioterápicos.", "explicacao": "Exigem dupla checagem."}, {"id": 2000002543, "trilha": "saude", "materia": "enf", "assunto": "Medicamentos", "tipo": "pergunta", "frente": "O cloreto de potássio concentrado pode ser administrado em bolus?", "verso": "Nunca. Deve ser diluído e infundido lentamente, pois pode causar parada cardíaca.", "explicacao": ""}, {"id": 2000002544, "trilha": "saude", "materia": "enf", "assunto": "Medicamentos", "tipo": "pergunta", "frente": "Qual o antídoto da heparina e da varfarina?", "verso": "Heparina: sulfato de protamina. Varfarina: vitamina K.", "explicacao": ""}, {"id": 2000002545, "trilha": "saude", "materia": "enf", "assunto": "Medicamentos", "tipo": "pergunta", "frente": "Qual o antídoto dos opioides e dos benzodiazepínicos?", "verso": "Opioides: naloxona. Benzodiazepínicos: flumazenil.", "explicacao": ""}, {"id": 2000002546, "trilha": "saude", "materia": "enf", "assunto": "Medicamentos", "tipo": "pares", "frente": "Insulina regular x NPH.", "verso": "Regular: ação rápida, pode ser aplicada por via endovenosa, aspecto límpido. NPH: ação intermediária, aspecto turvo, só subcutânea.", "explicacao": "Ao misturar, aspira-se primeiro a regular."}, {"id": 2000002547, "trilha": "saude", "materia": "enf", "assunto": "Segurança do paciente", "tipo": "pergunta", "frente": "Quais são as seis metas internacionais de segurança do paciente?", "verso": "Identificar corretamente o paciente; melhorar a comunicação; melhorar a segurança de medicamentos de alta vigilância; cirurgia segura; higienizar as mãos; reduzir o risco de quedas e lesões por pressão.", "explicacao": "Programa Nacional de Segurança do Paciente (Portaria MS 529/2013)."}, {"id": 2000002548, "trilha": "saude", "materia": "enf", "assunto": "Segurança do paciente", "tipo": "pergunta", "frente": "Quantos identificadores devem ser usados para identificar o paciente?", "verso": "Pelo menos dois (ex.: nome completo e data de nascimento).", "explicacao": "O número do leito não deve ser usado como identificador."}, {"id": 2000002549, "trilha": "saude", "materia": "enf", "assunto": "Segurança do paciente", "tipo": "pergunta", "frente": "Quais os cinco momentos para a higiene das mãos (OMS)?", "verso": "Antes de tocar o paciente; antes de procedimento limpo/asséptico; após risco de exposição a fluidos corporais; após tocar o paciente; após tocar superfícies próximas ao paciente.", "explicacao": ""}, {"id": 2000002550, "trilha": "saude", "materia": "enf", "assunto": "Segurança do paciente", "tipo": "pergunta", "frente": "Quando a higiene das mãos deve ser feita com água e sabonete, e não com álcool?", "verso": "Quando as mãos estiverem visivelmente sujas ou contaminadas com material proteico, e após contato com pacientes com Clostridioides difficile.", "explicacao": ""}, {"id": 2000002551, "trilha": "saude", "materia": "enf", "assunto": "Segurança do paciente", "tipo": "pergunta", "frente": "Quais as etapas do checklist de cirurgia segura (OMS)?", "verso": "Antes da indução anestésica (sign in), antes da incisão (time out) e antes de o paciente sair da sala (sign out).", "explicacao": ""}, {"id": 2000002552, "trilha": "saude", "materia": "enf", "assunto": "Segurança do paciente", "tipo": "pergunta", "frente": "O que é evento adverso?", "verso": "Incidente que resulta em dano ao paciente.", "explicacao": "Near miss (quase erro): incidente que não atingiu o paciente."}, {"id": 2000002553, "trilha": "saude", "materia": "enf", "assunto": "Segurança do paciente", "tipo": "pergunta", "frente": "Qual escala avalia o risco de lesão por pressão?", "verso": "Escala de Braden.", "explicacao": "Quanto menor o escore, maior o risco."}, {"id": 2000002554, "trilha": "saude", "materia": "enf", "assunto": "Segurança do paciente", "tipo": "pergunta", "frente": "Qual escala avalia o risco de quedas?", "verso": "Escala de Morse.", "explicacao": ""}, {"id": 2000002555, "trilha": "saude", "materia": "enf", "assunto": "Lesão por pressão", "tipo": "pergunta", "frente": "Como se classifica a lesão por pressão estágio 1?", "verso": "Pele íntegra com eritema que não embranquece.", "explicacao": "NPIAP."}, {"id": 2000002556, "trilha": "saude", "materia": "enf", "assunto": "Lesão por pressão", "tipo": "pares", "frente": "Lesão por pressão estágio 2 x 3 x 4.", "verso": "Estágio 2: perda parcial da pele com exposição da derme. Estágio 3: perda total da pele, com tecido adiposo visível. Estágio 4: perda total da pele e perda tissular, com exposição de fáscia, músculo, tendão ou osso.", "explicacao": "Há também a não classificável e a tissular profunda."}, {"id": 2000002557, "trilha": "saude", "materia": "enf", "assunto": "Lesão por pressão", "tipo": "pergunta", "frente": "Com que frequência mínima se faz mudança de decúbito no paciente acamado em risco?", "verso": "A cada 2 horas, em geral, ajustando ao risco e à superfície de apoio.", "explicacao": ""}, {"id": 2000002558, "trilha": "saude", "materia": "enf", "assunto": "Feridas", "tipo": "pergunta", "frente": "O que é cicatrização por primeira intenção?", "verso": "Bordas aproximadas (sutura), com pouca perda tecidual, cicatrização rápida.", "explicacao": "Segunda intenção: bordas afastadas, cicatriza por granulação. Terceira: fechamento tardio."}, {"id": 2000002559, "trilha": "saude", "materia": "enf", "assunto": "Feridas", "tipo": "pergunta", "frente": "Para que serve a papaína em feridas?", "verso": "Desbridamento enzimático do tecido necrótico, conforme a concentração.", "explicacao": ""}, {"id": 2000002560, "trilha": "saude", "materia": "enf", "assunto": "Feridas", "tipo": "pergunta", "frente": "Para que serve o curativo com alginato de cálcio?", "verso": "Feridas com exsudato moderado a intenso e sangramento, pois é absorvente e hemostático.", "explicacao": ""}, {"id": 2000002561, "trilha": "saude", "materia": "enf", "assunto": "Feridas", "tipo": "pergunta", "frente": "Para que serve o hidrocoloide?", "verso": "Feridas com pouco a moderado exsudato e prevenção de lesões por pressão; mantém meio úmido e estimula o desbridamento autolítico.", "explicacao": "Contraindicado em feridas infectadas."}, {"id": 2000002562, "trilha": "saude", "materia": "enf", "assunto": "Feridas", "tipo": "pergunta", "frente": "O que é o AGE (ácidos graxos essenciais) em feridas?", "verso": "Óleo que mantém o meio úmido, acelera a granulação e protege a pele íntegra.", "explicacao": ""}, {"id": 2000002563, "trilha": "saude", "materia": "enf", "assunto": "Biossegurança", "tipo": "pares", "frente": "Limpeza x desinfecção x esterilização.", "verso": "Limpeza: remoção de sujidade. Desinfecção: eliminação de microrganismos, exceto esporos (alto, médio ou baixo nível). Esterilização: eliminação de todas as formas de vida, inclusive esporos.", "explicacao": ""}, {"id": 2000002564, "trilha": "saude", "materia": "enf", "assunto": "Biossegurança", "tipo": "pares", "frente": "Artigos críticos x semicríticos x não críticos (Spaulding).", "verso": "Críticos: penetram tecidos estéreis (instrumental cirúrgico) — esterilização. Semicríticos: contato com mucosa ou pele não íntegra (endoscópio) — desinfecção de alto nível. Não críticos: contato com pele íntegra (estetoscópio) — limpeza ou desinfecção de baixo/médio nível.", "explicacao": ""}, {"id": 2000002565, "trilha": "saude", "materia": "enf", "assunto": "Biossegurança", "tipo": "pergunta", "frente": "Qual o método de esterilização mais usado em hospitais para artigos resistentes ao calor?", "verso": "Autoclave (vapor saturado sob pressão).", "explicacao": "Termossensíveis: óxido de etileno, plasma de peróxido de hidrogênio."}, {"id": 2000002566, "trilha": "saude", "materia": "enf", "assunto": "Biossegurança", "tipo": "pergunta", "frente": "Qual indicador biológico se usa para monitorar autoclaves?", "verso": "Esporos de Geobacillus stearothermophilus.", "explicacao": ""}, {"id": 2000002567, "trilha": "saude", "materia": "enf", "assunto": "Biossegurança", "tipo": "pergunta", "frente": "Qual norma regulamentadora trata da segurança e saúde no trabalho em serviços de saúde?", "verso": "NR 32.", "explicacao": "Proíbe reencapar agulhas e exige vacinação contra hepatite B, tétano e difteria."}, {"id": 2000002568, "trilha": "saude", "materia": "enf", "assunto": "Biossegurança", "tipo": "pergunta", "frente": "Qual a capacidade máxima de preenchimento da caixa de perfurocortantes?", "verso": "Até a linha indicada (2/3 ou cerca de 5 cm abaixo da boca), nunca até o topo.", "explicacao": ""}, {"id": 2000002569, "trilha": "saude", "materia": "enf", "assunto": "Biossegurança", "tipo": "pares", "frente": "Precaução de contato x gotículas x aerossóis.", "verso": "Contato: luvas e avental (ex.: bactérias multirresistentes). Gotículas: máscara cirúrgica (ex.: influenza, meningite meningocócica). Aerossóis: máscara N95/PFF2 e quarto com pressão negativa (ex.: tuberculose, sarampo, varicela).", "explicacao": "Precaução padrão vale para todos os pacientes."}, {"id": 2000002570, "trilha": "saude", "materia": "enf", "assunto": "Biossegurança", "tipo": "pergunta", "frente": "Qual a conduta imediata após acidente com material perfurocortante?", "verso": "Lavar o local com água e sabão (não espremer), comunicar e procurar atendimento para avaliar profilaxia, de preferência nas primeiras 2 horas, no máximo até 72 horas.", "explicacao": "Notificação obrigatória (CAT e Sinan)."}, {"id": 2000002571, "trilha": "saude", "materia": "enf", "assunto": "Biossegurança", "tipo": "pergunta", "frente": "Qual a cor do grupo de resíduos de saúde do grupo A (infectantes) no saco?", "verso": "Branco leitoso, com símbolo de risco biológico.", "explicacao": "RDC Anvisa 222/2018."}, {"id": 2000002572, "trilha": "saude", "materia": "enf", "assunto": "Biossegurança", "tipo": "pares", "frente": "Grupos de resíduos de serviços de saúde.", "verso": "A: infectantes. B: químicos. C: radioativos. D: comuns (equiparados aos domiciliares). E: perfurocortantes.", "explicacao": "RDC Anvisa 222/2018."}, {"id": 2000002573, "trilha": "saude", "materia": "enf", "assunto": "Imunização", "tipo": "pergunta", "frente": "Qual a temperatura de conservação das vacinas na rede de frio?", "verso": "Entre +2 °C e +8 °C (ideal +5 °C), na instância local.", "explicacao": ""}, {"id": 2000002574, "trilha": "saude", "materia": "enf", "assunto": "Imunização", "tipo": "pergunta", "frente": "Quais vacinas o recém-nascido recebe ao nascer?", "verso": "BCG (dose única) e hepatite B (primeira dose, de preferência nas primeiras 24 horas).", "explicacao": "Calendário Nacional de Vacinação."}, {"id": 2000002575, "trilha": "saude", "materia": "enf", "assunto": "Imunização", "tipo": "pergunta", "frente": "Qual a via de administração da vacina BCG?", "verso": "Intradérmica, na inserção inferior do músculo deltoide direito.", "explicacao": ""}, {"id": 2000002576, "trilha": "saude", "materia": "enf", "assunto": "Imunização", "tipo": "pergunta", "frente": "Em que idades se aplica a vacina pentavalente?", "verso": "2, 4 e 6 meses.", "explicacao": "Protege contra difteria, tétano, coqueluche, hepatite B e Haemophilus influenzae tipo b."}, {"id": 2000002577, "trilha": "saude", "materia": "enf", "assunto": "Imunização", "tipo": "pergunta", "frente": "Qual a vacina contra a poliomielite usada nas doses do primeiro ano?", "verso": "Vacina inativada poliomielite (VIP), aos 2, 4 e 6 meses.", "explicacao": "Desde 2024 a VOP (gotinha) foi substituída pela VIP também no reforço."}, {"id": 2000002578, "trilha": "saude", "materia": "enf", "assunto": "Imunização", "tipo": "pergunta", "frente": "Quando se aplica a tríplice viral?", "verso": "Aos 12 meses; aos 15 meses aplica-se a tetra viral (ou tríplice viral + varicela).", "explicacao": "Protege contra sarampo, caxumba e rubéola."}, {"id": 2000002579, "trilha": "saude", "materia": "enf", "assunto": "Imunização", "tipo": "pergunta", "frente": "A gestante pode receber vacinas de vírus vivo atenuado?", "verso": "Em regra, não (ex.: tríplice viral, febre amarela salvo situações especiais).", "explicacao": "Na gestação: dTpa, hepatite B, influenza e covid-19."}, {"id": 2000002580, "trilha": "saude", "materia": "enf", "assunto": "Imunização", "tipo": "pergunta", "frente": "A partir de que semana a gestante recebe a dTpa?", "verso": "A partir da 20ª semana de gestação, em cada gestação.", "explicacao": "Protege o bebê contra coqueluche."}, {"id": 2000002581, "trilha": "saude", "materia": "enf", "assunto": "Imunização", "tipo": "pergunta", "frente": "O que é ESAVI?", "verso": "Evento supostamente atribuível à vacinação ou imunização.", "explicacao": "Antigo EAPV."}, {"id": 2000002582, "trilha": "saude", "materia": "enf", "assunto": "Urgência e emergência", "tipo": "pergunta", "frente": "Qual a sequência do atendimento à parada cardiorrespiratória no adulto (AHA)?", "verso": "C-A-B: compressões, via aérea e respiração.", "explicacao": "Reconhecer, chamar ajuda e pedir o DEA."}, {"id": 2000002583, "trilha": "saude", "materia": "enf", "assunto": "Urgência e emergência", "tipo": "pergunta", "frente": "Qual a frequência e a profundidade das compressões torácicas no adulto?", "verso": "100 a 120 por minuto, com profundidade de 5 a 6 cm, permitindo retorno total do tórax.", "explicacao": "AHA."}, {"id": 2000002584, "trilha": "saude", "materia": "enf", "assunto": "Urgência e emergência", "tipo": "pergunta", "frente": "Qual a relação compressão-ventilação na RCP do adulto sem via aérea avançada?", "verso": "30 compressões para 2 ventilações.", "explicacao": "Com via aérea avançada: compressões contínuas e 1 ventilação a cada 6 segundos."}, {"id": 2000002585, "trilha": "saude", "materia": "enf", "assunto": "Urgência e emergência", "tipo": "pares", "frente": "Ritmos chocáveis x não chocáveis na PCR.", "verso": "Chocáveis: fibrilação ventricular e taquicardia ventricular sem pulso. Não chocáveis: assistolia e atividade elétrica sem pulso (AESP).", "explicacao": ""}, {"id": 2000002586, "trilha": "saude", "materia": "enf", "assunto": "Urgência e emergência", "tipo": "pergunta", "frente": "Qual a dose e o intervalo da epinefrina na PCR do adulto?", "verso": "1 mg EV/IO a cada 3 a 5 minutos.", "explicacao": "Amiodarona: 300 mg e depois 150 mg em ritmos chocáveis refratários."}, {"id": 2000002587, "trilha": "saude", "materia": "enf", "assunto": "Urgência e emergência", "tipo": "pergunta", "frente": "O que avalia a escala de coma de Glasgow?", "verso": "Abertura ocular, resposta verbal e resposta motora, com escore de 3 a 15 (ou com reatividade pupilar, de 1 a 15).", "explicacao": "Escore ≤ 8: indicação de via aérea definitiva."}, {"id": 2000002588, "trilha": "saude", "materia": "enf", "assunto": "Urgência e emergência", "tipo": "pergunta", "frente": "Qual o protocolo de classificação de risco mais usado nas emergências?", "verso": "Protocolo de Manchester, com cinco cores: vermelho (emergência), laranja (muito urgente), amarelo (urgente), verde (pouco urgente) e azul (não urgente).", "explicacao": ""}, {"id": 2000002589, "trilha": "saude", "materia": "enf", "assunto": "Urgência e emergência", "tipo": "pergunta", "frente": "Qual a sequência do atendimento ao politraumatizado (XABCDE)?", "verso": "X: hemorragia exsanguinante; A: via aérea com proteção cervical; B: respiração; C: circulação; D: estado neurológico; E: exposição e controle da hipotermia.", "explicacao": "PHTLS/ATLS."}, {"id": 2000002590, "trilha": "saude", "materia": "enf", "assunto": "Urgência e emergência", "tipo": "pergunta", "frente": "Como se faz a desobstrução de vias aéreas em adulto consciente engasgado?", "verso": "Manobra de Heimlich: compressões abdominais subdiafragmáticas.", "explicacao": "Em lactentes: 5 golpes nas costas e 5 compressões torácicas."}, {"id": 2000002591, "trilha": "saude", "materia": "enf", "assunto": "Urgência e emergência", "tipo": "pergunta", "frente": "Quais os sinais do choque hipovolêmico?", "verso": "Taquicardia, hipotensão, pele fria e pegajosa, palidez, enchimento capilar lento, oligúria e alteração do nível de consciência.", "explicacao": ""}, {"id": 2000002592, "trilha": "saude", "materia": "enf", "assunto": "Urgência e emergência", "tipo": "pergunta", "frente": "Qual a regra dos nove no queimado adulto?", "verso": "Cabeça e pescoço 9%; cada membro superior 9%; tronco anterior 18%; tronco posterior 18%; cada membro inferior 18%; períneo 1%.", "explicacao": "Estima a superfície corporal queimada."}, {"id": 2000002593, "trilha": "saude", "materia": "enf", "assunto": "Urgência e emergência", "tipo": "pergunta", "frente": "Como se calcula a hidratação do grande queimado pela fórmula de Parkland?", "verso": "4 mL × peso (kg) × % de superfície queimada nas primeiras 24 h, com metade nas primeiras 8 horas.", "explicacao": "Usa-se Ringer lactato."}, {"id": 2000002594, "trilha": "saude", "materia": "enf", "assunto": "Urgência e emergência", "tipo": "pergunta", "frente": "Qual a conduta inicial na hipoglicemia em paciente consciente?", "verso": "Oferecer 15 g de carboidrato de absorção rápida e reavaliar a glicemia em 15 minutos.", "explicacao": "Inconsciente: glicose a 50% EV."}, {"id": 2000002595, "trilha": "saude", "materia": "enf", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Como se confirma o posicionamento da sonda nasogástrica?", "verso": "O padrão-ouro é a radiografia; à beira do leito, aspiração de conteúdo gástrico (com teste de pH quando disponível).", "explicacao": "A ausculta de ar insuflado sozinha não é confiável."}, {"id": 2000002596, "trilha": "saude", "materia": "enf", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Como se mede o comprimento da sonda nasogástrica a ser introduzida?", "verso": "Da ponta do nariz ao lóbulo da orelha e daí ao apêndice xifoide.", "explicacao": "Para sonda nasoenteral, acrescenta-se uma medida adicional."}, {"id": 2000002597, "trilha": "saude", "materia": "enf", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Em que posição se coloca o paciente para passar a sonda nasogástrica?", "verso": "Fowler alto (sentado), com a cabeça levemente fletida na hora de deglutir.", "explicacao": ""}, {"id": 2000002598, "trilha": "saude", "materia": "enf", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Quem pode realizar a sondagem vesical na equipe de enfermagem?", "verso": "Privativamente o enfermeiro.", "explicacao": "Resolução Cofen 450/2013."}, {"id": 2000002599, "trilha": "saude", "materia": "enf", "assunto": "Procedimentos", "tipo": "pares", "frente": "Sondagem vesical de alívio x de demora.", "verso": "Alívio: esvaziamento da bexiga e retirada da sonda em seguida. Demora: sonda permanece, com balão insuflado e sistema fechado de drenagem.", "explicacao": "Técnica estéril em ambas."}, {"id": 2000002600, "trilha": "saude", "materia": "enf", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Onde deve ficar a bolsa coletora da sonda vesical?", "verso": "Abaixo do nível da bexiga, sem tocar o chão, com o sistema sempre fechado.", "explicacao": "Previne refluxo e infecção urinária."}, {"id": 2000002601, "trilha": "saude", "materia": "enf", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Qual a pressão do sistema de aspiração de vias aéreas em adultos e a duração de cada aspiração?", "verso": "Em geral até 150 mmHg (de 80 a 150), por no máximo 10 a 15 segundos.", "explicacao": "Aspira-se ao retirar a sonda."}, {"id": 2000002602, "trilha": "saude", "materia": "enf", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Qual a ordem de aspiração de vias aéreas no paciente intubado?", "verso": "Primeiro o tubo orotraqueal, depois a boca (e o nariz), com a mesma sonda descartada em seguida.", "explicacao": "Do mais limpo para o mais contaminado."}, {"id": 2000002603, "trilha": "saude", "materia": "enf", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Qual a pressão do cuff do tubo orotraqueal recomendada?", "verso": "Entre 20 e 30 cmH₂O (aproximadamente 18 a 22 mmHg).", "explicacao": "Excesso causa isquemia da mucosa traqueal."}, {"id": 2000002604, "trilha": "saude", "materia": "enf", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Qual o fluxo de oxigênio no cateter nasal tipo óculos em adultos?", "verso": "Até cerca de 5 a 6 L/min, oferecendo FiO₂ de 24% a 44%.", "explicacao": "Cada litro acrescenta cerca de 4%."}, {"id": 2000002605, "trilha": "saude", "materia": "enf", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Qual a vantagem da máscara de Venturi?", "verso": "Fornece FiO₂ precisa e controlada.", "explicacao": "Útil na DPOC."}, {"id": 2000002606, "trilha": "saude", "materia": "enf", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Qual posição se usa para lavagem intestinal (enteroclisma)?", "verso": "Sims (decúbito lateral esquerdo com a perna direita fletida).", "explicacao": "Segue a anatomia do sigmoide."}, {"id": 2000002607, "trilha": "saude", "materia": "enf", "assunto": "Procedimentos", "tipo": "pares", "frente": "Posição de Fowler x Trendelenburg x litotômica.", "verso": "Fowler: sentado ou semissentado (cabeceira 45° a 60°). Trendelenburg: cabeça mais baixa que os pés. Litotômica (ginecológica): decúbito dorsal com pernas fletidas e afastadas.", "explicacao": "Proclive (Trendelenburg reverso): cabeça mais alta."}, {"id": 2000002608, "trilha": "saude", "materia": "enf", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Qual a elevação da cabeceira recomendada para prevenir pneumonia associada à ventilação mecânica?", "verso": "Entre 30° e 45°.", "explicacao": "Integra o bundle de prevenção da PAV."}, {"id": 2000002609, "trilha": "saude", "materia": "enf", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Em que veia se puncionam preferencialmente os acessos periféricos do adulto?", "verso": "Nas veias dos membros superiores, de distal para proximal, evitando articulações.", "explicacao": "Evitar membros com fístula, mastectomia homolateral ou plegia."}, {"id": 2000002610, "trilha": "saude", "materia": "enf", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Com que frequência se troca o cateter venoso periférico em adultos?", "verso": "Não há troca em intervalo fixo obrigatório; recomenda-se avaliar diariamente e trocar quando indicado clinicamente (ou em até 96 horas, conforme protocolo institucional).", "explicacao": "Anvisa."}, {"id": 2000002611, "trilha": "saude", "materia": "enf", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "O que é flebite e como se previne?", "verso": "Inflamação da veia, com dor, calor, rubor e cordão palpável; previne-se com técnica asséptica, fixação adequada, diluição correta e avaliação frequente do acesso.", "explicacao": ""}, {"id": 2000002612, "trilha": "saude", "materia": "enf", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Qual a diferença entre infiltração e extravasamento?", "verso": "Infiltração: solução não vesicante sai para o tecido. Extravasamento: solução vesicante (como quimioterápicos), que pode necrosar o tecido.", "explicacao": ""}, {"id": 2000002613, "trilha": "saude", "materia": "enf", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Como se coleta a urina para urocultura?", "verso": "Jato médio, após higiene íntima, em frasco estéril; em sonda de demora, punciona-se o dispositivo próprio, nunca da bolsa.", "explicacao": ""}, {"id": 2000002614, "trilha": "saude", "materia": "enf", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Qual a ordem dos tubos na coleta de sangue a vácuo?", "verso": "Hemocultura, citrato (azul), soro (vermelho/amarelo), heparina (verde), EDTA (roxo) e fluoreto (cinza).", "explicacao": "Evita contaminação por aditivos."}, {"id": 2000002615, "trilha": "saude", "materia": "enf", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Qual a dosagem de glicemia capilar indicativa de hipoglicemia em adultos?", "verso": "Abaixo de 70 mg/dL.", "explicacao": ""}, {"id": 2000002616, "trilha": "saude", "materia": "enf", "assunto": "Transfusão", "tipo": "pergunta", "frente": "Quanto tempo o enfermeiro deve ficar ao lado do paciente no início da transfusão?", "verso": "Nos primeiros 10 minutos, observando reações.", "explicacao": "Verificar sinais vitais antes, durante e depois."}, {"id": 2000002617, "trilha": "saude", "materia": "enf", "assunto": "Transfusão", "tipo": "pergunta", "frente": "Qual o tempo máximo de infusão de uma bolsa de concentrado de hemácias?", "verso": "4 horas.", "explicacao": ""}, {"id": 2000002618, "trilha": "saude", "materia": "enf", "assunto": "Transfusão", "tipo": "pergunta", "frente": "O que fazer diante de reação transfusional?", "verso": "Interromper a transfusão imediatamente, manter acesso com soro fisiológico, avisar o médico e o banco de sangue e verificar sinais vitais.", "explicacao": "Não descartar a bolsa."}, {"id": 2000002619, "trilha": "saude", "materia": "enf", "assunto": "Transfusão", "tipo": "pergunta", "frente": "Que solução pode correr junto com hemocomponentes no mesmo acesso?", "verso": "Apenas soro fisiológico 0,9%.", "explicacao": "Glicose causa hemólise; soluções com cálcio causam coagulação."}, {"id": 2000002620, "trilha": "saude", "materia": "enf", "assunto": "Saúde da mulher", "tipo": "pergunta", "frente": "Qual o número mínimo de consultas de pré-natal recomendado pelo Ministério da Saúde?", "verso": "No mínimo 6 consultas (a OMS recomenda 8 contatos).", "explicacao": "Primeira consulta até a 12ª semana."}, {"id": 2000002621, "trilha": "saude", "materia": "enf", "assunto": "Saúde da mulher", "tipo": "pergunta", "frente": "O enfermeiro pode realizar consulta de pré-natal de baixo risco?", "verso": "Sim, pode acompanhar integralmente o pré-natal de baixo risco.", "explicacao": "Lei 7.498/1986 e protocolos do MS."}, {"id": 2000002622, "trilha": "saude", "materia": "enf", "assunto": "Saúde da mulher", "tipo": "pergunta", "frente": "Como se calcula a data provável do parto pela regra de Naegele?", "verso": "Soma-se 7 dias ao primeiro dia da última menstruação e subtrai-se 3 meses (ou soma-se 9).", "explicacao": "Ex.: DUM 10/04 → DPP 17/01."}, {"id": 2000002623, "trilha": "saude", "materia": "enf", "assunto": "Saúde da mulher", "tipo": "pergunta", "frente": "A partir de quando se mede a altura uterina e qual sua relação com a idade gestacional?", "verso": "A partir de cerca de 20 semanas, quando a altura (em cm) corresponde aproximadamente à idade gestacional em semanas, até cerca de 32 semanas.", "explicacao": "Na 12ª semana o útero está na sínfise púbica; na 20ª, na cicatriz umbilical."}, {"id": 2000002624, "trilha": "saude", "materia": "enf", "assunto": "Saúde da mulher", "tipo": "pergunta", "frente": "Quais os exames do primeiro trimestre do pré-natal?", "verso": "Hemograma, tipagem sanguínea e fator Rh, glicemia, urina e urocultura, testes rápidos para HIV, sífilis e hepatites B e C, toxoplasmose, entre outros.", "explicacao": ""}, {"id": 2000002625, "trilha": "saude", "materia": "enf", "assunto": "Saúde da mulher", "tipo": "pergunta", "frente": "Qual o tratamento da sífilis na gestante?", "verso": "Penicilina benzatina; é o único medicamento que trata o feto.", "explicacao": "O parceiro também deve ser tratado."}, {"id": 2000002626, "trilha": "saude", "materia": "enf", "assunto": "Saúde da mulher", "tipo": "pergunta", "frente": "Quais os sinais da pré-eclâmpsia?", "verso": "Hipertensão (≥ 140 x 90 mmHg) após 20 semanas, com proteinúria ou sinais de lesão de órgão-alvo.", "explicacao": "Eclâmpsia: convulsões. Tratamento das convulsões: sulfato de magnésio."}, {"id": 2000002627, "trilha": "saude", "materia": "enf", "assunto": "Saúde da mulher", "tipo": "pergunta", "frente": "Qual o antídoto do sulfato de magnésio?", "verso": "Gluconato de cálcio.", "explicacao": "Monitorar reflexo patelar, frequência respiratória e diurese."}, {"id": 2000002628, "trilha": "saude", "materia": "enf", "assunto": "Saúde da mulher", "tipo": "pergunta", "frente": "Quais os quatro períodos clínicos do parto?", "verso": "Dilatação, expulsão, dequitação (saída da placenta) e Greenberg (1ª hora após a dequitação).", "explicacao": ""}, {"id": 2000002629, "trilha": "saude", "materia": "enf", "assunto": "Saúde da mulher", "tipo": "pergunta", "frente": "Qual a principal causa de hemorragia pós-parto?", "verso": "Atonia uterina.", "explicacao": "Prevenção: ocitocina 10 UI IM após o nascimento."}, {"id": 2000002630, "trilha": "saude", "materia": "enf", "assunto": "Saúde da mulher", "tipo": "pares", "frente": "Lóquios rubros x serosos x alvos.", "verso": "Rubros: avermelhados, nos primeiros dias. Serosos: rosados/acastanhados, até cerca de 10 dias. Alvos: esbranquiçados, depois.", "explicacao": ""}, {"id": 2000002631, "trilha": "saude", "materia": "enf", "assunto": "Saúde da mulher", "tipo": "pergunta", "frente": "Com que idade começa o rastreamento do câncer do colo do útero pelo citopatológico?", "verso": "Aos 25 anos, para mulheres que já tiveram atividade sexual, até os 64 anos.", "explicacao": "Após dois exames anuais normais, a cada 3 anos. O MS vem implantando o teste de DNA-HPV."}, {"id": 2000002632, "trilha": "saude", "materia": "enf", "assunto": "Saúde da mulher", "tipo": "pergunta", "frente": "Qual a faixa etária do rastreamento do câncer de mama com mamografia pelo MS?", "verso": "Dos 50 aos 69 anos, a cada 2 anos.", "explicacao": "Em 2025 o MS ampliou o acesso a partir dos 40 anos sob demanda."}, {"id": 2000002633, "trilha": "saude", "materia": "enf", "assunto": "Saúde da criança", "tipo": "pergunta", "frente": "Qual o índice de Apgar e quando se avalia?", "verso": "Avalia frequência cardíaca, esforço respiratório, tônus, irritabilidade reflexa e cor, no 1º e no 5º minuto de vida (0 a 10).", "explicacao": "Apgar ≥ 7: boa vitalidade."}, {"id": 2000002634, "trilha": "saude", "materia": "enf", "assunto": "Saúde da criança", "tipo": "pergunta", "frente": "Quais os testes de triagem neonatal obrigatórios?", "verso": "Teste do pezinho, da orelhinha, do olhinho, do coraçãozinho e da linguinha.", "explicacao": ""}, {"id": 2000002635, "trilha": "saude", "materia": "enf", "assunto": "Saúde da criança", "tipo": "pergunta", "frente": "Quando se coleta o teste do pezinho?", "verso": "Entre o 3º e o 5º dia de vida.", "explicacao": ""}, {"id": 2000002636, "trilha": "saude", "materia": "enf", "assunto": "Saúde da criança", "tipo": "pergunta", "frente": "Até que idade se recomenda aleitamento materno exclusivo?", "verso": "Até os 6 meses; complementado até 2 anos ou mais.", "explicacao": ""}, {"id": 2000002637, "trilha": "saude", "materia": "enf", "assunto": "Saúde da criança", "tipo": "pergunta", "frente": "Quais os sinais de pega correta na amamentação?", "verso": "Boca bem aberta, lábio inferior virado para fora, queixo tocando a mama e mais aréola visível acima da boca do que abaixo.", "explicacao": ""}, {"id": 2000002638, "trilha": "saude", "materia": "enf", "assunto": "Saúde da criança", "tipo": "pergunta", "frente": "Qual a frequência cardíaca normal do recém-nascido?", "verso": "Entre 120 e 160 bpm.", "explicacao": "FR do RN: 40 a 60 irpm."}, {"id": 2000002639, "trilha": "saude", "materia": "enf", "assunto": "Saúde da criança", "tipo": "pergunta", "frente": "O que é a icterícia fisiológica do recém-nascido?", "verso": "Amarelamento que surge após 24 horas de vida, por imaturidade hepática, e regride espontaneamente.", "explicacao": "Icterícia nas primeiras 24 horas é patológica."}, {"id": 2000002640, "trilha": "saude", "materia": "enf", "assunto": "Saúde da criança", "tipo": "pergunta", "frente": "Quais os cuidados de enfermagem com o recém-nascido em fototerapia?", "verso": "Proteção ocular, exposição máxima da pele, controle de temperatura, hidratação e mudança de decúbito.", "explicacao": ""}, {"id": 2000002641, "trilha": "saude", "materia": "enf", "assunto": "Saúde da criança", "tipo": "pergunta", "frente": "Qual o sinal de desidratação grave na criança (AIDPI)?", "verso": "Letargia ou inconsciência, olhos fundos, não consegue beber e sinal da prega que desaparece muito lentamente (mais de 2 segundos).", "explicacao": "Plano C: hidratação venosa."}, {"id": 2000002642, "trilha": "saude", "materia": "enf", "assunto": "Saúde da criança", "tipo": "pares", "frente": "Plano A x B x C (diarreia).", "verso": "A: sem desidratação, tratamento em casa com mais líquidos e soro. B: com desidratação, terapia de reidratação oral na unidade. C: desidratação grave, hidratação venosa.", "explicacao": ""}, {"id": 2000002643, "trilha": "saude", "materia": "enf", "assunto": "Saúde do adulto", "tipo": "pergunta", "frente": "Qual o valor de glicemia de jejum que define diabetes?", "verso": "Igual ou maior que 126 mg/dL em duas ocasiões.", "explicacao": "HbA1c ≥ 6,5% ou glicemia ao acaso ≥ 200 com sintomas."}, {"id": 2000002644, "trilha": "saude", "materia": "enf", "assunto": "Saúde do adulto", "tipo": "pergunta", "frente": "Quais os sinais clássicos de hiperglicemia?", "verso": "Poliúria, polidipsia, polifagia e perda de peso.", "explicacao": "Os “4 Ps”."}, {"id": 2000002645, "trilha": "saude", "materia": "enf", "assunto": "Saúde do adulto", "tipo": "pergunta", "frente": "Quais cuidados com os pés do diabético?", "verso": "Inspeção diária, higiene e secagem entre os dedos, hidratação (sem entre os dedos), cortar unhas retas, calçados adequados e nunca andar descalço.", "explicacao": ""}, {"id": 2000002646, "trilha": "saude", "materia": "enf", "assunto": "Saúde do adulto", "tipo": "pergunta", "frente": "Onde fazer rodízio da aplicação de insulina?", "verso": "Abdome, face posterior do braço, face anterior e lateral da coxa e região glútea, mantendo distância entre as aplicações.", "explicacao": "Previne lipodistrofia."}, {"id": 2000002647, "trilha": "saude", "materia": "enf", "assunto": "Saúde do adulto", "tipo": "pergunta", "frente": "Quais os sinais de alerta de AVC (escala de Cincinnati/SAMU)?", "verso": "Desvio da face, fraqueza de um braço e alteração da fala.", "explicacao": "Tempo é cérebro: trombólise em até 4,5 h no isquêmico."}, {"id": 2000002648, "trilha": "saude", "materia": "enf", "assunto": "Saúde do adulto", "tipo": "pergunta", "frente": "Quais os sinais típicos do infarto agudo do miocárdio?", "verso": "Dor torácica em aperto, irradiando para braço esquerdo, mandíbula ou costas, com sudorese, náusea e dispneia.", "explicacao": "Idosos, mulheres e diabéticos podem ter sintomas atípicos."}, {"id": 2000002649, "trilha": "saude", "materia": "enf", "assunto": "Saúde do adulto", "tipo": "pergunta", "frente": "Qual o cuidado de enfermagem no paciente com insuficiência cardíaca descompensada?", "verso": "Cabeceira elevada, controle de peso diário, balanço hídrico, restrição de sódio e líquidos conforme prescrição e observação de edema e dispneia.", "explicacao": ""}, {"id": 2000002650, "trilha": "saude", "materia": "enf", "assunto": "Saúde do adulto", "tipo": "pergunta", "frente": "O que é balanço hídrico?", "verso": "Registro de todos os líquidos administrados e eliminados em determinado período, para avaliar ganho ou perda.", "explicacao": ""}, {"id": 2000002651, "trilha": "saude", "materia": "enf", "assunto": "Centro cirúrgico", "tipo": "pares", "frente": "Cirurgia limpa x potencialmente contaminada x contaminada x infectada.", "verso": "Limpa: tecidos estéreis, sem inflamação. Potencialmente contaminada: penetra tratos com flora (digestivo, respiratório) sem contaminação significativa. Contaminada: tecidos com flora abundante ou quebra de técnica. Infectada: com processo infeccioso ou tecido necrótico.", "explicacao": ""}, {"id": 2000002652, "trilha": "saude", "materia": "enf", "assunto": "Centro cirúrgico", "tipo": "pergunta", "frente": "O que é a sala de recuperação pós-anestésica e qual escala se usa?", "verso": "Local de observação após a anestesia; usa-se o índice de Aldrete e Kroulik (atividade, respiração, circulação, consciência e saturação).", "explicacao": "Alta com escore ≥ 8 (geralmente)."}, {"id": 2000002653, "trilha": "saude", "materia": "enf", "assunto": "Centro cirúrgico", "tipo": "pergunta", "frente": "Qual a função do circulante de sala?", "verso": "Prover materiais, auxiliar a equipe sem tocar o campo estéril, posicionar o paciente e registrar o procedimento.", "explicacao": "O instrumentador atua no campo estéril."}, {"id": 2000002654, "trilha": "saude", "materia": "enf", "assunto": "Centro cirúrgico", "tipo": "pergunta", "frente": "Até onde deve ser feita a tricotomia pré-operatória?", "verso": "Só quando necessário, imediatamente antes da cirurgia (até 2 horas antes), com tricotomizador elétrico, não lâmina.", "explicacao": "Previne infecção do sítio cirúrgico."}, {"id": 2000002655, "trilha": "saude", "materia": "enf", "assunto": "CME", "tipo": "pergunta", "frente": "Quais as áreas da Central de Material e Esterilização?", "verso": "Expurgo (recepção e limpeza), preparo e acondicionamento, esterilização e armazenamento e distribuição.", "explicacao": "RDC Anvisa 15/2012."}, {"id": 2000002656, "trilha": "saude", "materia": "enf", "assunto": "CME", "tipo": "pergunta", "frente": "O fluxo de materiais na CME deve ser como?", "verso": "Unidirecional: da área suja para a área limpa, sem cruzamento.", "explicacao": ""}, {"id": 2000002657, "trilha": "saude", "materia": "enf", "assunto": "Infecção hospitalar", "tipo": "pergunta", "frente": "Quando uma infecção é considerada relacionada à assistência à saúde (IRAS)?", "verso": "Quando adquirida após a admissão e se manifesta durante a internação ou após a alta, se relacionada à internação ou a procedimentos.", "explicacao": "Em geral, a partir de 48 horas da admissão."}, {"id": 2000002658, "trilha": "saude", "materia": "enf", "assunto": "Infecção hospitalar", "tipo": "pergunta", "frente": "Qual a comissão obrigatória nos hospitais para prevenir infecções?", "verso": "A Comissão de Controle de Infecção Hospitalar (CCIH).", "explicacao": "Lei 9.431/1997 e Portaria MS 2.616/1998."}, {"id": 2000002659, "trilha": "saude", "materia": "enf", "assunto": "Saúde mental", "tipo": "pergunta", "frente": "O que são os CAPS?", "verso": "Centros de Atenção Psicossocial, serviços comunitários abertos para pessoas com sofrimento mental grave e persistente e problemas com álcool e drogas.", "explicacao": "Rede de Atenção Psicossocial (RAPS)."}, {"id": 2000002660, "trilha": "saude", "materia": "enf", "assunto": "Saúde mental", "tipo": "pergunta", "frente": "Qual lei trata da reforma psiquiátrica no Brasil?", "verso": "Lei 10.216/2001.", "explicacao": "Prioriza o tratamento em serviços comunitários; a internação só quando os recursos extra-hospitalares forem insuficientes."}, {"id": 2000002661, "trilha": "saude", "materia": "enf", "assunto": "Saúde mental", "tipo": "pares", "frente": "Internação voluntária x involuntária x compulsória.", "verso": "Voluntária: com consentimento do paciente. Involuntária: sem consentimento, a pedido de terceiro, comunicada ao MP em 72 horas. Compulsória: determinada pela Justiça.", "explicacao": "Lei 10.216/2001, art. 6º."}, {"id": 2000002662, "trilha": "saude", "materia": "enf", "assunto": "Saúde do idoso", "tipo": "pergunta", "frente": "Quais os gigantes da geriatria?", "verso": "Instabilidade e quedas, incontinência, imobilidade, insuficiência cognitiva e iatrogenia.", "explicacao": ""}, {"id": 2000002663, "trilha": "saude", "materia": "enf", "assunto": "Saúde do idoso", "tipo": "pergunta", "frente": "Qual a idade que define pessoa idosa no Brasil?", "verso": "60 anos ou mais.", "explicacao": "Estatuto da Pessoa Idosa (Lei 10.741/2003)."}, {"id": 2000002664, "trilha": "saude", "materia": "enf", "assunto": "Saúde do trabalhador", "tipo": "pergunta", "frente": "Quais vacinas são recomendadas aos profissionais de saúde?", "verso": "Hepatite B, dT (difteria e tétano), tríplice viral, influenza e covid-19, além de varicela para suscetíveis.", "explicacao": "NR 32 exige hepatite B, tétano e difteria gratuitamente."}, {"id": 2000002665, "trilha": "saude", "materia": "enf", "assunto": "Doenças transmissíveis", "tipo": "pergunta", "frente": "Qual o tratamento padrão da tuberculose pulmonar em adultos?", "verso": "Esquema básico de 6 meses: 2 meses de rifampicina, isoniazida, pirazinamida e etambutol (RIPE) e 4 meses de rifampicina e isoniazida (RI).", "explicacao": "Tratamento diretamente observado é recomendado."}, {"id": 2000002666, "trilha": "saude", "materia": "enf", "assunto": "Doenças transmissíveis", "tipo": "pergunta", "frente": "Como se faz a prova tuberculínica (PPD)?", "verso": "Injeção intradérmica no antebraço esquerdo e leitura em 48 a 72 horas, medindo o maior diâmetro transverso da enduração.", "explicacao": ""}, {"id": 2000002667, "trilha": "saude", "materia": "enf", "assunto": "Doenças transmissíveis", "tipo": "pergunta", "frente": "Quais os sinais de alarme na dengue?", "verso": "Dor abdominal intensa e contínua, vômitos persistentes, acúmulo de líquidos, sangramento de mucosas, letargia, hepatomegalia e aumento progressivo do hematócrito.", "explicacao": "Costumam surgir na defervescência da febre."}, {"id": 2000002668, "trilha": "saude", "materia": "enf", "assunto": "Doenças transmissíveis", "tipo": "pergunta", "frente": "Qual a prova do laço e para que serve?", "verso": "Insufla-se o manguito na pressão média entre sistólica e diastólica por 5 min (adulto) e contam-se petéquias num quadrado de 2,5 cm; positiva com 20 ou mais em adultos.", "explicacao": "Triagem de fragilidade capilar na dengue."}, {"id": 2000002669, "trilha": "saude", "materia": "enf", "assunto": "Doenças transmissíveis", "tipo": "pergunta", "frente": "Qual o agente da hanseníase e como se transmite?", "verso": "Mycobacterium leprae; pelas vias aéreas superiores, em contato próximo e prolongado com doente não tratado.", "explicacao": "Tratamento com poliquimioterapia (PQT-U)."}, {"id": 2000002670, "trilha": "saude", "materia": "enf", "assunto": "Doenças transmissíveis", "tipo": "pares", "frente": "Hanseníase paucibacilar x multibacilar.", "verso": "Paucibacilar: até 5 lesões de pele; tratamento de 6 meses. Multibacilar: mais de 5 lesões; tratamento de 12 meses.", "explicacao": ""}, {"id": 2000002671, "trilha": "saude", "materia": "enf", "assunto": "Vigilância", "tipo": "pergunta", "frente": "O que é notificação compulsória?", "verso": "Comunicação obrigatória à autoridade de saúde da ocorrência de suspeita ou confirmação de doença, agravo ou evento da lista nacional.", "explicacao": "Feita por médicos, profissionais de saúde e responsáveis por estabelecimentos."}, {"id": 2000002672, "trilha": "saude", "materia": "enf", "assunto": "Vigilância", "tipo": "pares", "frente": "Notificação imediata x semanal.", "verso": "Imediata: em até 24 horas (ex.: sarampo, raiva humana, cólera). Semanal: em até 7 dias (ex.: hanseníase, tuberculose).", "explicacao": ""}, {"id": 2000002673, "trilha": "saude", "materia": "enf", "assunto": "Vigilância", "tipo": "pergunta", "frente": "O que é o Sinan?", "verso": "Sistema de Informação de Agravos de Notificação.", "explicacao": "SIM: mortalidade. Sinasc: nascidos vivos."}, {"id": 2000002674, "trilha": "saude", "materia": "enf", "assunto": "Atenção básica", "tipo": "pergunta", "frente": "O que é a Estratégia Saúde da Família?", "verso": "Modelo prioritário de organização da atenção básica, com equipes multiprofissionais responsáveis por população adscrita em território definido.", "explicacao": "Equipe mínima: médico, enfermeiro, técnico ou auxiliar de enfermagem e agentes comunitários de saúde."}, {"id": 2000002675, "trilha": "saude", "materia": "enf", "assunto": "Atenção básica", "tipo": "pergunta", "frente": "Qual o número recomendado de pessoas por equipe de Saúde da Família?", "verso": "De 2.000 a 3.500 pessoas por equipe.", "explicacao": "PNAB 2017."}, {"id": 2000002676, "trilha": "saude", "materia": "enf", "assunto": "Atenção básica", "tipo": "pergunta", "frente": "O que é visita domiciliar na atenção básica?", "verso": "Atendimento no domicílio para acompanhar a família, identificar riscos e oferecer cuidado e orientação.", "explicacao": ""}, {"id": 2000002677, "trilha": "saude", "materia": "enf", "assunto": "Administração em enfermagem", "tipo": "pergunta", "frente": "O que é dimensionamento de pessoal de enfermagem?", "verso": "Cálculo do número e da categoria de profissionais necessários, conforme o grau de dependência dos pacientes.", "explicacao": "Resolução Cofen 743/2024."}, {"id": 2000002678, "trilha": "saude", "materia": "enf", "assunto": "Administração em enfermagem", "tipo": "pergunta", "frente": "Quais as categorias do Sistema de Classificação de Pacientes (Fugulin)?", "verso": "Cuidados mínimos, intermediários, de alta dependência, semi-intensivos e intensivos.", "explicacao": ""}, {"id": 2000002679, "trilha": "saude", "materia": "enf", "assunto": "Administração em enfermagem", "tipo": "pergunta", "frente": "Quais os requisitos de um bom registro (anotação) de enfermagem?", "verso": "Ser legível, completo, objetivo, cronológico, sem rasuras, com data, hora, assinatura e número do Coren.", "explicacao": "É documento legal."}, {"id": 2000002680, "trilha": "saude", "materia": "enf", "assunto": "Administração em enfermagem", "tipo": "pergunta", "frente": "Como corrigir um erro no registro de enfermagem?", "verso": "Não rasurar nem usar corretivo; escrever “digo” ou “em tempo” e fazer a anotação correta.", "explicacao": ""}, {"id": 2000002681, "trilha": "saude", "materia": "enf", "assunto": "Terminologia", "tipo": "pares", "frente": "Anúria x oligúria x poliúria.", "verso": "Anúria: diurese abaixo de 100 mL/24 h. Oligúria: abaixo de 400 mL/24 h. Poliúria: acima de 2.500 a 3.000 mL/24 h.", "explicacao": ""}, {"id": 2000002682, "trilha": "saude", "materia": "enf", "assunto": "Terminologia", "tipo": "pares", "frente": "Disúria x nictúria x hematúria.", "verso": "Disúria: dor ao urinar. Nictúria: urinar à noite. Hematúria: sangue na urina.", "explicacao": ""}, {"id": 2000002683, "trilha": "saude", "materia": "enf", "assunto": "Terminologia", "tipo": "pares", "frente": "Hematêmese x melena x hemoptise.", "verso": "Hematêmese: vômito com sangue. Melena: fezes escuras com sangue digerido. Hemoptise: sangue eliminado com a tosse.", "explicacao": "Enterorragia: sangue vivo nas fezes."}, {"id": 2000002684, "trilha": "saude", "materia": "enf", "assunto": "Terminologia", "tipo": "pares", "frente": "Cianose x icterícia x palidez.", "verso": "Cianose: coloração azulada por baixa oxigenação. Icterícia: amarelada, por bilirrubina. Palidez: falta de cor, comum na anemia e no choque.", "explicacao": ""}, {"id": 2000002685, "trilha": "saude", "materia": "enf", "assunto": "Terminologia", "tipo": "pares", "frente": "Afasia x disfagia x disartria.", "verso": "Afasia: perda da capacidade de linguagem. Disfagia: dificuldade de engolir. Disartria: dificuldade de articular as palavras.", "explicacao": ""}, {"id": 2000002686, "trilha": "saude", "materia": "enf", "assunto": "Terminologia", "tipo": "pares", "frente": "Hemiplegia x paraplegia x tetraplegia.", "verso": "Hemiplegia: paralisia de um lado do corpo. Paraplegia: dos membros inferiores. Tetraplegia: dos quatro membros.", "explicacao": "Paresia: perda parcial da força."}, {"id": 2000002687, "trilha": "saude", "materia": "enf", "assunto": "Terminologia", "tipo": "pares", "frente": "Edema x anasarca x ascite.", "verso": "Edema: acúmulo de líquido no interstício. Anasarca: edema generalizado. Ascite: líquido na cavidade peritoneal.", "explicacao": ""}, {"id": 2000002688, "trilha": "saude", "materia": "enf", "assunto": "Terminologia", "tipo": "pergunta", "frente": "O que é o sinal de cacifo (Godet)?", "verso": "Depressão que permanece na pele após pressionar com o dedo uma área edemaciada.", "explicacao": "Graduado de + a ++++."}, {"id": 2000002689, "trilha": "saude", "materia": "enf", "assunto": "Terminologia", "tipo": "pares", "frente": "Exame físico: inspeção x palpação x percussão x ausculta.", "verso": "Ordem geral: inspeção, palpação, percussão e ausculta. No abdome: inspeção, ausculta, percussão e palpação.", "explicacao": "No abdome, ausculta antes para não alterar os ruídos."}, {"id": 2000002690, "trilha": "saude", "materia": "enf", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Qual o tempo de jejum recomendado antes de cirurgia eletiva em adultos?", "verso": "Em geral 8 horas para refeições completas, 6 horas para refeição leve e 2 horas para líquidos claros.", "explicacao": "Diretrizes de anestesiologia; seguir protocolo institucional."}, {"id": 2000002691, "trilha": "saude", "materia": "enf", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Qual a posição para punção lombar?", "verso": "Decúbito lateral com joelhos fletidos sobre o abdome e queixo no peito (posição fetal), ou sentado curvado para frente.", "explicacao": ""}, {"id": 2000002692, "trilha": "saude", "materia": "enf", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Como se faz a higiene oral em paciente intubado?", "verso": "Com clorexidina 0,12% ou conforme protocolo, cabeceira elevada, aspiração e cuidado com a fixação do tubo.", "explicacao": "Parte da prevenção de pneumonia associada à ventilação."}, {"id": 2000002693, "trilha": "saude", "materia": "enf", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Qual a técnica para administrar colírio?", "verso": "Paciente com a cabeça inclinada para trás, puxar a pálpebra inferior e pingar no saco conjuntival, sem tocar o olho com o frasco.", "explicacao": "Pressionar o canto interno do olho reduz a absorção sistêmica."}, {"id": 2000002694, "trilha": "saude", "materia": "enf", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "O que é a escala de Ramsay?", "verso": "Escala de sedação com 6 níveis, de ansioso e agitado (1) a sem resposta (6).", "explicacao": ""}, {"id": 2000002695, "trilha": "saude", "materia": "enf", "assunto": "Medicamentos", "tipo": "pergunta", "frente": "Quantas gotas correm por minuto para infundir 1.000 mL em 24 horas?", "verso": "Cerca de 14 gotas/min.", "explicacao": "1.000 ÷ (24 × 3) = 13,9."}, {"id": 2000002696, "trilha": "saude", "materia": "enf", "assunto": "Medicamentos", "tipo": "pergunta", "frente": "Qual a velocidade em mL/h de uma bomba para infundir 500 mL em 6 horas?", "verso": "Cerca de 83 mL/h.", "explicacao": "500 ÷ 6."}, {"id": 2000002697, "trilha": "saude", "materia": "enf", "assunto": "Medicamentos", "tipo": "pergunta", "frente": "Como preparar 100 mL de SG 10% a partir de SG 5% e glicose 50%?", "verso": "Usa-se regra de mistura: cerca de 89 mL de SG 5% e 11 mL de glicose 50% (5,5 g + 4,45 g ≈ 10 g).", "explicacao": "Questão clássica de cálculo."}, {"id": 2000002698, "trilha": "saude", "materia": "enf", "assunto": "Saúde da criança", "tipo": "pergunta", "frente": "Quais as vacinas aplicadas aos 2 meses de idade?", "verso": "Pentavalente, VIP, pneumocócica 10-valente e rotavírus.", "explicacao": "Calendário Nacional de Vacinação."}, {"id": 2000002699, "trilha": "saude", "materia": "enf", "assunto": "Saúde da criança", "tipo": "pergunta", "frente": "Qual o limite de idade para a primeira dose da vacina rotavírus?", "verso": "Até 3 meses e 15 dias; a segunda dose até 7 meses e 29 dias.", "explicacao": ""}, {"id": 2000002700, "trilha": "saude", "materia": "enf", "assunto": "Saúde do adulto", "tipo": "pergunta", "frente": "Qual a principal orientação sobre o uso de nitroglicerina sublingual na angina?", "verso": "Usar sentado, até 3 doses com intervalo de 5 minutos e procurar emergência se a dor não passar.", "explicacao": "Pode causar hipotensão e cefaleia."}, {"id": 2000002701, "trilha": "saude", "materia": "enf", "assunto": "Saúde mental", "tipo": "pergunta", "frente": "Qual a conduta da enfermagem diante de paciente com ideação suicida?", "verso": "Escuta acolhedora sem julgamento, perguntar diretamente sobre o risco, não deixar sozinho em risco alto, retirar meios letais e encaminhar para avaliação.", "explicacao": "Perguntar sobre suicídio não aumenta o risco."}, {"id": 2000002702, "trilha": "saude", "materia": "sus", "assunto": "Constituição", "tipo": "pergunta", "frente": "O que diz o art. 196 da Constituição sobre saúde?", "verso": "A saúde é direito de todos e dever do Estado, garantido mediante políticas sociais e econômicas que visem à redução do risco de doença e ao acesso universal e igualitário às ações e serviços.", "explicacao": ""}, {"id": 2000002703, "trilha": "saude", "materia": "sus", "assunto": "Constituição", "tipo": "pergunta", "frente": "Quais as diretrizes do SUS na Constituição?", "verso": "Descentralização, com direção única em cada esfera de governo; atendimento integral, com prioridade para as atividades preventivas; e participação da comunidade.", "explicacao": "CF, art. 198."}, {"id": 2000002704, "trilha": "saude", "materia": "sus", "assunto": "Constituição", "tipo": "pergunta", "frente": "A iniciativa privada pode participar do SUS?", "verso": "Sim, de forma complementar, mediante contrato de direito público ou convênio, com preferência para entidades filantrópicas e sem fins lucrativos.", "explicacao": "CF, art. 199, § 1º."}, {"id": 2000002705, "trilha": "saude", "materia": "sus", "assunto": "Constituição", "tipo": "pergunta", "frente": "É permitida a destinação de recursos públicos a instituições privadas com fins lucrativos na saúde?", "verso": "Não, para auxílios ou subvenções.", "explicacao": "CF, art. 199, § 2º."}, {"id": 2000002706, "trilha": "saude", "materia": "sus", "assunto": "Constituição", "tipo": "pergunta", "frente": "É permitida a participação de capital estrangeiro na assistência à saúde?", "verso": "É vedada, salvo nos casos previstos em lei.", "explicacao": "CF, art. 199, § 3º. A Lei 13.097/2015 ampliou as exceções."}, {"id": 2000002707, "trilha": "saude", "materia": "sus", "assunto": "Constituição", "tipo": "pergunta", "frente": "A comercialização de órgãos, tecidos e sangue é permitida?", "verso": "Não. É vedado todo tipo de comercialização.", "explicacao": "CF, art. 199, § 4º."}, {"id": 2000002708, "trilha": "saude", "materia": "sus", "assunto": "Constituição", "tipo": "pergunta", "frente": "Cite atribuições do SUS no art. 200 da CF.", "verso": "Controlar e fiscalizar produtos de interesse para a saúde, executar vigilância sanitária e epidemiológica e saúde do trabalhador, ordenar a formação de recursos humanos, saneamento básico, fiscalizar alimentos e água e colaborar na proteção do meio ambiente, incluído o do trabalho.", "explicacao": "CF, art. 200."}, {"id": 2000002709, "trilha": "saude", "materia": "sus", "assunto": "Constituição", "tipo": "pergunta", "frente": "Qual o percentual mínimo que a União aplica em saúde?", "verso": "15% da receita corrente líquida do exercício.", "explicacao": "CF, art. 198, § 2º, I (EC 86/2015)."}, {"id": 2000002710, "trilha": "saude", "materia": "sus", "assunto": "Constituição", "tipo": "pergunta", "frente": "Quais os percentuais mínimos de estados e municípios em saúde?", "verso": "Estados: 12% e municípios: 15% da receita de impostos e transferências.", "explicacao": "LC 141/2012."}, {"id": 2000002711, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "O que regula a Lei 8.080/1990?", "verso": "As condições para promoção, proteção e recuperação da saúde, a organização e o funcionamento dos serviços (Lei Orgânica da Saúde).", "explicacao": ""}, {"id": 2000002712, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "A saúde, para a Lei 8.080, depende só de serviços de saúde?", "verso": "Não. Tem como determinantes e condicionantes alimentação, moradia, saneamento, meio ambiente, trabalho, renda, educação, atividade física, transporte, lazer e acesso a bens e serviços essenciais.", "explicacao": "Lei 8.080/1990, art. 3º."}, {"id": 2000002713, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "Como a Lei 8.080 define o SUS?", "verso": "Conjunto de ações e serviços de saúde prestados por órgãos e instituições públicas federais, estaduais e municipais, da administração direta e indireta e das fundações mantidas pelo Poder Público.", "explicacao": "Lei 8.080/1990, art. 4º."}, {"id": 2000002714, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "Quais os objetivos do SUS na Lei 8.080?", "verso": "Identificar e divulgar os fatores condicionantes e determinantes da saúde, formular a política de saúde e prestar assistência por ações de promoção, proteção e recuperação.", "explicacao": "Lei 8.080/1990, art. 5º."}, {"id": 2000002715, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "Como a Lei 8.080 define vigilância sanitária?", "verso": "Ações capazes de eliminar, diminuir ou prevenir riscos à saúde e de intervir nos problemas sanitários do meio ambiente, da produção e circulação de bens e da prestação de serviços de interesse da saúde.", "explicacao": "Lei 8.080/1990, art. 6º, § 1º."}, {"id": 2000002716, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "Como a Lei 8.080 define vigilância epidemiológica?", "verso": "Ações que proporcionam o conhecimento, a detecção ou prevenção de mudanças nos fatores determinantes e condicionantes da saúde individual ou coletiva, para recomendar e adotar medidas de prevenção e controle das doenças ou agravos.", "explicacao": "Lei 8.080/1990, art. 6º, § 2º."}, {"id": 2000002717, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "O que compreende a saúde do trabalhador na Lei 8.080?", "verso": "Ações de vigilância epidemiológica e sanitária para promoção, proteção, recuperação e reabilitação da saúde dos trabalhadores submetidos a riscos e agravos das condições de trabalho.", "explicacao": "Lei 8.080/1990, art. 6º, § 3º."}, {"id": 2000002718, "trilha": "saude", "materia": "sus", "assunto": "Princípios", "tipo": "pares", "frente": "Princípios doutrinários do SUS.", "verso": "Universalidade (acesso a todos), integralidade (conjunto articulado de ações preventivas e curativas, individuais e coletivas, em todos os níveis) e equidade (tratar desigualmente os desiguais, priorizando quem mais precisa).", "explicacao": "A Lei 8.080 fala em igualdade da assistência, sem preconceitos ou privilégios."}, {"id": 2000002719, "trilha": "saude", "materia": "sus", "assunto": "Princípios", "tipo": "pares", "frente": "Princípios organizativos do SUS.", "verso": "Regionalização, hierarquização, descentralização com direção única em cada esfera, participação popular e resolubilidade.", "explicacao": ""}, {"id": 2000002720, "trilha": "saude", "materia": "sus", "assunto": "Princípios", "tipo": "pergunta", "frente": "Cite princípios do art. 7º da Lei 8.080.", "verso": "Universalidade de acesso, integralidade, preservação da autonomia, igualdade, direito à informação, divulgação de informações, epidemiologia para estabelecer prioridades, participação da comunidade, descentralização, integração com meio ambiente e saneamento, conjugação de recursos, resolubilidade e organização para evitar duplicidade.", "explicacao": "Lei 8.080/1990, art. 7º."}, {"id": 2000002721, "trilha": "saude", "materia": "sus", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que é integralidade?", "verso": "Conjunto articulado e contínuo de ações e serviços preventivos e curativos, individuais e coletivos, exigidos em cada caso, em todos os níveis de complexidade.", "explicacao": "Lei 8.080/1990, art. 7º, II."}, {"id": 2000002722, "trilha": "saude", "materia": "sus", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que é a direção única em cada esfera de governo?", "verso": "União: Ministério da Saúde. Estados e DF: secretarias estaduais de saúde. Municípios: secretarias municipais de saúde.", "explicacao": "Lei 8.080/1990, art. 9º."}, {"id": 2000002723, "trilha": "saude", "materia": "sus", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que é a ênfase na municipalização?", "verso": "A descentralização político-administrativa com ênfase na transferência de serviços para os municípios.", "explicacao": "Lei 8.080/1990, art. 7º, IX, a."}, {"id": 2000002724, "trilha": "saude", "materia": "sus", "assunto": "Competências", "tipo": "pergunta", "frente": "Cite competências da direção nacional do SUS.", "verso": "Formular, avaliar e apoiar políticas; definir e coordenar sistemas de redes integradas de alta complexidade, rede de laboratórios, vigilância epidemiológica e sanitária de portos, aeroportos e fronteiras; normatizar e coordenar o Sistema Nacional de Sangue.", "explicacao": "Lei 8.080/1990, art. 16."}, {"id": 2000002725, "trilha": "saude", "materia": "sus", "assunto": "Competências", "tipo": "pergunta", "frente": "Qual a principal competência da direção municipal do SUS?", "verso": "Planejar, organizar, controlar e avaliar as ações e serviços de saúde e gerir e executar os serviços públicos de saúde.", "explicacao": "Lei 8.080/1990, art. 18."}, {"id": 2000002726, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "O que é o Subsistema de Atenção à Saúde Indígena?", "verso": "Componente do SUS, financiado pela União, que garante atenção diferenciada aos povos indígenas, levando em conta sua cultura.", "explicacao": "Lei 8.080/1990, arts. 19-A a 19-H (Lei Arouca). Organizado em DSEIs."}, {"id": 2000002727, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "Qual o direito garantido à parturiente no SUS?", "verso": "Presença de um acompanhante de sua escolha durante o trabalho de parto, parto e pós-parto imediato.", "explicacao": "Lei 8.080/1990, art. 19-J (Lei 11.108/2005)."}, {"id": 2000002728, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "O que é atendimento e internação domiciliar no SUS?", "verso": "Atendimento médico, de enfermagem, fisioterapêutico, psicológico e de assistência social realizado no domicílio, por indicação médica e com concordância do paciente e da família.", "explicacao": "Lei 8.080/1990, art. 19-I."}, {"id": 2000002729, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "Como o SUS incorpora novos medicamentos e tecnologias?", "verso": "Por decisão do Ministério da Saúde, assessorado pela Conitec (Comissão Nacional de Incorporação de Tecnologias).", "explicacao": "Lei 8.080/1990, art. 19-Q."}, {"id": 2000002730, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "O que a assistência terapêutica integral do SUS inclui?", "verso": "Dispensação de medicamentos e produtos conforme diretrizes terapêuticas (PCDT) e oferta de procedimentos terapêuticos constantes de tabelas do gestor.", "explicacao": "Lei 8.080/1990, art. 19-M."}, {"id": 2000002731, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "Quais as comissões intergestores do SUS?", "verso": "Comissão Intergestores Tripartite (União, estados e municípios), Bipartite (estado e municípios) e Regional.", "explicacao": "Lei 8.080/1990, art. 14-A; Decreto 7.508/2011."}, {"id": 2000002732, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "O que são o Conass e o Conasems?", "verso": "Conselho Nacional de Secretários de Saúde e Conselho Nacional de Secretarias Municipais de Saúde, reconhecidos como entidades representativas dos entes estaduais e municipais.", "explicacao": "Lei 8.080/1990, art. 14-B."}, {"id": 2000002733, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.142", "tipo": "pergunta", "frente": "O que regula a Lei 8.142/1990?", "verso": "A participação da comunidade na gestão do SUS e as transferências intergovernamentais de recursos financeiros.", "explicacao": ""}, {"id": 2000002734, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.142", "tipo": "pergunta", "frente": "Quais as instâncias colegiadas do SUS?", "verso": "A Conferência de Saúde e o Conselho de Saúde, em cada esfera de governo.", "explicacao": "Lei 8.142/1990, art. 1º."}, {"id": 2000002735, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.142", "tipo": "pares", "frente": "Conferência de Saúde x Conselho de Saúde.", "verso": "Conferência: reúne-se a cada 4 anos para avaliar a situação de saúde e propor diretrizes. Conselho: permanente e deliberativo, atua na formulação de estratégias e no controle da execução da política, inclusive nos aspectos financeiros.", "explicacao": "Lei 8.142/1990, art. 1º, §§ 1º e 2º."}, {"id": 2000002736, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.142", "tipo": "pergunta", "frente": "Qual a composição paritária dos conselhos e conferências de saúde?", "verso": "A representação dos usuários é paritária em relação ao conjunto dos demais segmentos (50% usuários).", "explicacao": "Lei 8.142/1990, art. 1º, § 4º. Resolução CNS 453/2012: 50% usuários, 25% trabalhadores e 25% gestores e prestadores."}, {"id": 2000002737, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.142", "tipo": "pergunta", "frente": "Quem convoca a Conferência de Saúde?", "verso": "O Poder Executivo ou, extraordinariamente, a própria Conferência ou o Conselho de Saúde.", "explicacao": "Lei 8.142/1990, art. 1º, § 1º."}, {"id": 2000002738, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.142", "tipo": "pergunta", "frente": "Quem homologa as decisões do Conselho de Saúde?", "verso": "O chefe do poder legalmente constituído em cada esfera de governo.", "explicacao": "Lei 8.142/1990, art. 1º, § 2º."}, {"id": 2000002739, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.142", "tipo": "pergunta", "frente": "Quais requisitos os municípios precisam cumprir para receber recursos do Fundo Nacional de Saúde?", "verso": "Fundo de Saúde, Conselho de Saúde, plano de saúde, relatórios de gestão, contrapartida de recursos e comissão de elaboração do plano de carreiras, cargos e salários.", "explicacao": "Lei 8.142/1990, art. 4º."}, {"id": 2000002740, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.142", "tipo": "pergunta", "frente": "Como são repassados os recursos do Fundo Nacional de Saúde a estados e municípios?", "verso": "De forma regular e automática (fundo a fundo).", "explicacao": "Lei 8.142/1990, art. 3º."}, {"id": 2000002741, "trilha": "saude", "materia": "sus", "assunto": "Decreto 7.508", "tipo": "pergunta", "frente": "O que regulamenta o Decreto 7.508/2011?", "verso": "A Lei 8.080 quanto à organização do SUS, planejamento, assistência à saúde e articulação interfederativa.", "explicacao": ""}, {"id": 2000002742, "trilha": "saude", "materia": "sus", "assunto": "Decreto 7.508", "tipo": "pergunta", "frente": "O que é a Região de Saúde?", "verso": "Espaço geográfico contínuo formado por agrupamento de municípios limítrofes, com identidades culturais, econômicas e sociais e redes de comunicação e transporte compartilhados.", "explicacao": "Decreto 7.508/2011, art. 2º, I."}, {"id": 2000002743, "trilha": "saude", "materia": "sus", "assunto": "Decreto 7.508", "tipo": "pergunta", "frente": "Que ações mínimas uma Região de Saúde deve conter?", "verso": "Atenção primária, urgência e emergência, atenção psicossocial, atenção ambulatorial especializada e hospitalar e vigilância em saúde.", "explicacao": "Decreto 7.508/2011, art. 5º."}, {"id": 2000002744, "trilha": "saude", "materia": "sus", "assunto": "Decreto 7.508", "tipo": "pergunta", "frente": "Quais são as portas de entrada do SUS?", "verso": "Atenção primária, atenção de urgência e emergência, atenção psicossocial e serviços especiais de acesso aberto.", "explicacao": "Decreto 7.508/2011, art. 9º."}, {"id": 2000002745, "trilha": "saude", "materia": "sus", "assunto": "Decreto 7.508", "tipo": "pergunta", "frente": "O que é o Contrato Organizativo da Ação Pública da Saúde (COAP)?", "verso": "Acordo de colaboração entre entes federativos para organizar e integrar as ações e serviços de saúde na rede regionalizada e hierarquizada.", "explicacao": "Decreto 7.508/2011, art. 2º, II."}, {"id": 2000002746, "trilha": "saude", "materia": "sus", "assunto": "Decreto 7.508", "tipo": "pergunta", "frente": "O que são a RENASES e a RENAME?", "verso": "RENASES: Relação Nacional de Ações e Serviços de Saúde. RENAME: Relação Nacional de Medicamentos Essenciais.", "explicacao": "Decreto 7.508/2011, arts. 21 e 25."}, {"id": 2000002747, "trilha": "saude", "materia": "sus", "assunto": "Decreto 7.508", "tipo": "pergunta", "frente": "Quais os requisitos para acesso universal e igualitário à assistência farmacêutica?", "verso": "Estar assistido por ações e serviços do SUS, ter prescrição de profissional do SUS, prescrição conforme a RENAME e os protocolos, e dispensação em unidade indicada pela direção do SUS.", "explicacao": "Decreto 7.508/2011, art. 28."}, {"id": 2000002748, "trilha": "saude", "materia": "sus", "assunto": "Decreto 7.508", "tipo": "pergunta", "frente": "O que é o Mapa da Saúde?", "verso": "Descrição geográfica da distribuição de recursos humanos e de ações e serviços de saúde ofertados pelo SUS e pela iniciativa privada.", "explicacao": "Decreto 7.508/2011, art. 2º, V."}, {"id": 2000002749, "trilha": "saude", "materia": "sus", "assunto": "LC 141", "tipo": "pergunta", "frente": "O que regulamenta a LC 141/2012?", "verso": "Os valores mínimos a serem aplicados anualmente em ações e serviços públicos de saúde e os critérios de rateio e as normas de fiscalização.", "explicacao": ""}, {"id": 2000002750, "trilha": "saude", "materia": "sus", "assunto": "LC 141", "tipo": "pergunta", "frente": "Cite despesas que não são consideradas ações e serviços públicos de saúde pela LC 141.", "verso": "Pagamento de aposentadorias e pensões, merenda escolar, limpeza urbana, saneamento financiado por taxas, assistência a clientela fechada, preservação ambiental, obras de infraestrutura, entre outras.", "explicacao": "LC 141/2012, art. 4º."}, {"id": 2000002751, "trilha": "saude", "materia": "sus", "assunto": "Atenção básica", "tipo": "pergunta", "frente": "Qual a política que organiza a atenção básica no Brasil?", "verso": "A Política Nacional de Atenção Básica (PNAB), atualizada pela Portaria MS 2.436/2017.", "explicacao": ""}, {"id": 2000002752, "trilha": "saude", "materia": "sus", "assunto": "Atenção básica", "tipo": "pergunta", "frente": "Quais os atributos da atenção primária (Starfield)?", "verso": "Essenciais: primeiro contato (acesso), longitudinalidade, integralidade e coordenação do cuidado. Derivados: orientação familiar, orientação comunitária e competência cultural.", "explicacao": ""}, {"id": 2000002753, "trilha": "saude", "materia": "sus", "assunto": "Atenção básica", "tipo": "pergunta", "frente": "O que é longitudinalidade?", "verso": "Vínculo e acompanhamento contínuo da pessoa pela mesma equipe ao longo do tempo.", "explicacao": ""}, {"id": 2000002754, "trilha": "saude", "materia": "sus", "assunto": "Atenção básica", "tipo": "pergunta", "frente": "Qual o papel da atenção básica nas Redes de Atenção à Saúde?", "verso": "Ser a porta de entrada preferencial, a ordenadora da rede e a coordenadora do cuidado.", "explicacao": "PNAB 2017."}, {"id": 2000002755, "trilha": "saude", "materia": "sus", "assunto": "Atenção básica", "tipo": "pergunta", "frente": "O que faz o agente comunitário de saúde?", "verso": "Cadastra famílias, realiza visitas domiciliares, identifica situações de risco e faz o elo entre a comunidade e a equipe de saúde.", "explicacao": "Lei 11.350/2006. Deve residir na área em que atua."}, {"id": 2000002756, "trilha": "saude", "materia": "sus", "assunto": "Atenção básica", "tipo": "pergunta", "frente": "O que é o e-Multi?", "verso": "Equipes multiprofissionais na atenção primária, que substituíram os antigos NASF, apoiando as equipes de Saúde da Família.", "explicacao": "Portaria GM/MS 635/2023."}, {"id": 2000002757, "trilha": "saude", "materia": "sus", "assunto": "Atenção básica", "tipo": "pergunta", "frente": "O que é o programa Previne Brasil e o que o substituiu?", "verso": "Modelo de financiamento da APS de 2019 (capitação ponderada, pagamento por desempenho e incentivos); foi substituído em 2024 por novo cofinanciamento com componente fixo, de vínculo e acompanhamento e de qualidade.", "explicacao": "Portaria GM/MS 3.493/2024."}, {"id": 2000002758, "trilha": "saude", "materia": "sus", "assunto": "Redes de atenção", "tipo": "pergunta", "frente": "O que são as Redes de Atenção à Saúde (RAS)?", "verso": "Arranjos organizativos de ações e serviços de diferentes densidades tecnológicas, integrados por sistemas de apoio técnico, logístico e de gestão, para garantir a integralidade do cuidado.", "explicacao": "Portaria MS 4.279/2010."}, {"id": 2000002759, "trilha": "saude", "materia": "sus", "assunto": "Redes de atenção", "tipo": "pergunta", "frente": "Quais as redes temáticas prioritárias do SUS?", "verso": "Rede Cegonha (hoje Rede Alyne), Rede de Urgência e Emergência, Rede de Atenção Psicossocial, Rede de Cuidados à Pessoa com Deficiência e Rede de Atenção às Pessoas com Doenças Crônicas.", "explicacao": ""}, {"id": 2000002760, "trilha": "saude", "materia": "sus", "assunto": "Redes de atenção", "tipo": "pergunta", "frente": "O que é a Rede Alyne?", "verso": "Rede de cuidado materno-infantil lançada em 2024 que reestrutura a Rede Cegonha, com foco em reduzir a mortalidade materna, especialmente de mulheres negras.", "explicacao": "Homenagem a Alyne Pimentel."}, {"id": 2000002761, "trilha": "saude", "materia": "sus", "assunto": "Redes de atenção", "tipo": "pergunta", "frente": "Quais os componentes da Rede de Urgência e Emergência?", "verso": "Promoção e prevenção, atenção básica, SAMU 192, sala de estabilização, Força Nacional do SUS, UPA 24 h, atenção hospitalar e atenção domiciliar.", "explicacao": ""}, {"id": 2000002762, "trilha": "saude", "materia": "sus", "assunto": "Redes de atenção", "tipo": "pergunta", "frente": "O que é o SAMU 192?", "verso": "Serviço de Atendimento Móvel de Urgência, componente pré-hospitalar móvel da rede, com regulação médica das chamadas.", "explicacao": ""}, {"id": 2000002763, "trilha": "saude", "materia": "sus", "assunto": "Redes de atenção", "tipo": "pergunta", "frente": "O que é o Melhor em Casa?", "verso": "Serviço de atenção domiciliar do SUS, com equipes multiprofissionais (EMAD e EMAP).", "explicacao": ""}, {"id": 2000002764, "trilha": "saude", "materia": "sus", "assunto": "Políticas", "tipo": "pergunta", "frente": "O que é a Política Nacional de Humanização (HumanizaSUS)?", "verso": "Política transversal de 2003 que busca pôr em prática os princípios do SUS no cotidiano, valorizando usuários, trabalhadores e gestores.", "explicacao": "Diretrizes: acolhimento, gestão participativa, ambiência, clínica ampliada, valorização do trabalhador e defesa dos direitos dos usuários."}, {"id": 2000002765, "trilha": "saude", "materia": "sus", "assunto": "Políticas", "tipo": "pergunta", "frente": "O que é acolhimento com classificação de risco?", "verso": "Escuta qualificada e avaliação do usuário para priorizar o atendimento conforme a gravidade, e não por ordem de chegada.", "explicacao": "Diretriz da PNH."}, {"id": 2000002766, "trilha": "saude", "materia": "sus", "assunto": "Políticas", "tipo": "pergunta", "frente": "O que é clínica ampliada?", "verso": "Atenção que considera, além da doença, o sujeito e seu contexto, integrando diferentes saberes e envolvendo o usuário no cuidado.", "explicacao": "PNH."}, {"id": 2000002767, "trilha": "saude", "materia": "sus", "assunto": "Políticas", "tipo": "pergunta", "frente": "O que é o projeto terapêutico singular (PTS)?", "verso": "Conjunto de condutas terapêuticas articuladas, construídas pela equipe multiprofissional com o usuário, para casos complexos.", "explicacao": ""}, {"id": 2000002768, "trilha": "saude", "materia": "sus", "assunto": "Políticas", "tipo": "pergunta", "frente": "O que é a Política Nacional de Promoção da Saúde?", "verso": "Política que estimula ações sobre os determinantes sociais da saúde: alimentação saudável, atividade física, combate ao tabagismo, redução de danos pelo álcool, cultura de paz, entre outros.", "explicacao": "Portaria MS 687/2006, revisada em 2014."}, {"id": 2000002769, "trilha": "saude", "materia": "sus", "assunto": "Políticas", "tipo": "pergunta", "frente": "O que é a Política Nacional de Práticas Integrativas e Complementares (PNPIC)?", "verso": "Política que inclui no SUS práticas como acupuntura, homeopatia, fitoterapia, medicina antroposófica e termalismo, ampliadas depois com yoga, meditação, reiki e outras.", "explicacao": "Portaria MS 971/2006."}, {"id": 2000002770, "trilha": "saude", "materia": "sus", "assunto": "Políticas", "tipo": "pergunta", "frente": "O que é a Política Nacional de Saúde Integral da População Negra?", "verso": "Política que reconhece o racismo como determinante social da saúde e busca promover equidade para a população negra.", "explicacao": "Portaria MS 992/2009."}, {"id": 2000002771, "trilha": "saude", "materia": "sus", "assunto": "Políticas", "tipo": "pergunta", "frente": "Qual a Política Nacional de Atenção Integral à Saúde do Homem?", "verso": "Política de 2009 voltada aos homens de 20 a 59 anos, para ampliar o acesso e reduzir a morbimortalidade, com foco em prevenção.", "explicacao": "Portaria MS 1.944/2009."}, {"id": 2000002772, "trilha": "saude", "materia": "sus", "assunto": "Usuários", "tipo": "pergunta", "frente": "O que é a Carta dos Direitos e Deveres da Pessoa Usuária da Saúde?", "verso": "Documento que define direitos dos usuários: acesso ordenado, tratamento adequado e efetivo, atendimento humanizado e sem discriminação, respeito aos valores e direitos, e também deveres.", "explicacao": "Portaria MS 1.820/2009 (consolidada)."}, {"id": 2000002773, "trilha": "saude", "materia": "sus", "assunto": "Usuários", "tipo": "pergunta", "frente": "O paciente tem direito de consentir ou recusar procedimentos?", "verso": "Sim, de forma livre, voluntária e esclarecida, depois de informado, salvo risco à saúde pública.", "explicacao": "Carta dos Direitos dos Usuários."}, {"id": 2000002774, "trilha": "saude", "materia": "sus", "assunto": "Usuários", "tipo": "pergunta", "frente": "O que é a Ouvidoria do SUS?", "verso": "Canal de comunicação do cidadão com a gestão do SUS para reclamações, denúncias, sugestões, elogios e informações.", "explicacao": "Disque Saúde 136."}, {"id": 2000002775, "trilha": "saude", "materia": "sus", "assunto": "Vigilância", "tipo": "pergunta", "frente": "O que integra a vigilância em saúde?", "verso": "Vigilância epidemiológica, sanitária, ambiental e da saúde do trabalhador, além da promoção da saúde e análise da situação de saúde.", "explicacao": "Política Nacional de Vigilância em Saúde (Resolução CNS 588/2018)."}, {"id": 2000002776, "trilha": "saude", "materia": "sus", "assunto": "Vigilância", "tipo": "pergunta", "frente": "Qual a agência que coordena o Sistema Nacional de Vigilância Sanitária?", "verso": "A Anvisa.", "explicacao": "Lei 9.782/1999."}, {"id": 2000002777, "trilha": "saude", "materia": "sus", "assunto": "Vigilância", "tipo": "pergunta", "frente": "Qual agência regula os planos de saúde?", "verso": "A ANS (Agência Nacional de Saúde Suplementar).", "explicacao": "Lei 9.961/2000."}, {"id": 2000002778, "trilha": "saude", "materia": "sus", "assunto": "Vigilância", "tipo": "pergunta", "frente": "O que é o Cerest?", "verso": "Centro de Referência em Saúde do Trabalhador, que apoia ações de vigilância e assistência em saúde do trabalhador (Renast).", "explicacao": ""}, {"id": 2000002779, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "pares", "frente": "Incidência x prevalência.", "verso": "Incidência: casos novos em determinado período (mede risco). Prevalência: todos os casos existentes (novos e antigos) num momento ou período.", "explicacao": "Prevalência ≈ incidência × duração da doença."}, {"id": 2000002780, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "pares", "frente": "Endemia x epidemia x pandemia x surto.", "verso": "Endemia: ocorrência habitual numa região. Epidemia: aumento acima do esperado. Pandemia: epidemia em vários continentes. Surto: epidemia localizada (um bairro, uma escola).", "explicacao": ""}, {"id": 2000002781, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "pergunta", "frente": "Como se calcula o coeficiente de mortalidade infantil?", "verso": "Óbitos de menores de 1 ano ÷ nascidos vivos no ano × 1.000.", "explicacao": ""}, {"id": 2000002782, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "pares", "frente": "Mortalidade neonatal precoce x tardia x pós-neonatal.", "verso": "Neonatal precoce: 0 a 6 dias. Neonatal tardia: 7 a 27 dias. Pós-neonatal: 28 dias a menos de 1 ano.", "explicacao": ""}, {"id": 2000002783, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "pergunta", "frente": "Como se calcula a razão de mortalidade materna?", "verso": "Óbitos maternos ÷ nascidos vivos × 100.000.", "explicacao": "Morte materna: durante a gestação ou até 42 dias após, por causa relacionada."}, {"id": 2000002784, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "pares", "frente": "Letalidade x mortalidade.", "verso": "Letalidade: óbitos pela doença entre os doentes (gravidade). Mortalidade: óbitos em relação à população total.", "explicacao": ""}, {"id": 2000002785, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "pares", "frente": "Estudo de coorte x caso-controle x transversal.", "verso": "Coorte: acompanha expostos e não expostos ao longo do tempo (calcula risco relativo). Caso-controle: parte de doentes e não doentes e investiga exposição passada (odds ratio). Transversal: exposição e doença no mesmo momento (prevalência).", "explicacao": ""}, {"id": 2000002786, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "pares", "frente": "Sensibilidade x especificidade.", "verso": "Sensibilidade: capacidade do teste de identificar os doentes (verdadeiros positivos). Especificidade: capacidade de identificar os não doentes (verdadeiros negativos).", "explicacao": "Teste de triagem: alta sensibilidade."}, {"id": 2000002787, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "pergunta", "frente": "O que é transição epidemiológica?", "verso": "Mudança no perfil de doenças: queda das infecciosas e aumento das crônicas não transmissíveis e causas externas.", "explicacao": "No Brasil, há tripla carga de doenças."}, {"id": 2000002788, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "pares", "frente": "Prevenção primária x secundária x terciária x quaternária.", "verso": "Primária: evitar a doença (vacina). Secundária: detecção precoce e tratamento (rastreamento). Terciária: reduzir sequelas (reabilitação). Quaternária: evitar intervenções desnecessárias (iatrogenia).", "explicacao": "Leavell e Clark; quaternária de Jamoulle."}, {"id": 2000002789, "trilha": "saude", "materia": "sus", "assunto": "Sistemas de informação", "tipo": "pares", "frente": "SIM x Sinasc x Sinan x SIH x SIA.", "verso": "SIM: mortalidade (declaração de óbito). Sinasc: nascidos vivos (DNV). Sinan: agravos de notificação. SIH: internações hospitalares (AIH). SIA: atendimentos ambulatoriais.", "explicacao": ""}, {"id": 2000002790, "trilha": "saude", "materia": "sus", "assunto": "Sistemas de informação", "tipo": "pergunta", "frente": "O que é o e-SUS APS?", "verso": "Estratégia de informatização da atenção primária, com o Prontuário Eletrônico do Cidadão (PEC) e o sistema de informação SISAB.", "explicacao": ""}, {"id": 2000002791, "trilha": "saude", "materia": "sus", "assunto": "Sistemas de informação", "tipo": "pergunta", "frente": "O que é o CNES?", "verso": "Cadastro Nacional de Estabelecimentos de Saúde.", "explicacao": ""}, {"id": 2000002792, "trilha": "saude", "materia": "sus", "assunto": "Sistemas de informação", "tipo": "pergunta", "frente": "O que é o Cartão Nacional de Saúde (Cartão SUS)?", "verso": "Documento de identificação do usuário no SUS, com número único; hoje o CPF também é usado como identificador.", "explicacao": ""}, {"id": 2000002793, "trilha": "saude", "materia": "sus", "assunto": "Planejamento", "tipo": "pergunta", "frente": "Quais os instrumentos de planejamento do SUS?", "verso": "Plano de Saúde (4 anos), Programação Anual de Saúde e Relatório de Gestão (Relatório Anual e Relatório Detalhado do Quadrimestre Anterior).", "explicacao": "Portaria de Consolidação 1/2017."}, {"id": 2000002794, "trilha": "saude", "materia": "sus", "assunto": "Planejamento", "tipo": "pergunta", "frente": "A quem o gestor apresenta o Relatório Detalhado do Quadrimestre Anterior?", "verso": "Em audiência pública na Casa Legislativa e ao Conselho de Saúde.", "explicacao": "LC 141/2012, art. 36."}, {"id": 2000002795, "trilha": "saude", "materia": "sus", "assunto": "Planejamento", "tipo": "pergunta", "frente": "Até quando o Relatório Anual de Gestão deve ser enviado ao Conselho de Saúde?", "verso": "Até 30 de março do ano seguinte.", "explicacao": "LC 141/2012, art. 36, § 1º."}, {"id": 2000002796, "trilha": "saude", "materia": "sus", "assunto": "História", "tipo": "pergunta", "frente": "O que foi a 8ª Conferência Nacional de Saúde (1986)?", "verso": "Marco da Reforma Sanitária, que propôs a saúde como direito de todos e dever do Estado e as bases do SUS.", "explicacao": "Presidida por Sérgio Arouca."}, {"id": 2000002797, "trilha": "saude", "materia": "sus", "assunto": "História", "tipo": "pergunta", "frente": "O que era o INAMPS?", "verso": "Instituto Nacional de Assistência Médica da Previdência Social, que atendia só os trabalhadores com carteira assinada e seus dependentes.", "explicacao": "Extinto em 1993."}, {"id": 2000002798, "trilha": "saude", "materia": "sus", "assunto": "História", "tipo": "pergunta", "frente": "O que foram as Normas Operacionais Básicas (NOB)?", "verso": "Normas dos anos 1990 que regularam a descentralização e o financiamento do SUS (NOB 91, 93 e 96).", "explicacao": "NOB 96 criou o PAB."}, {"id": 2000002799, "trilha": "saude", "materia": "sus", "assunto": "História", "tipo": "pergunta", "frente": "O que foi o Pacto pela Saúde (2006)?", "verso": "Compromisso entre gestores com três dimensões: Pacto pela Vida, Pacto em Defesa do SUS e Pacto de Gestão.", "explicacao": "Portaria MS 399/2006."}, {"id": 2000002800, "trilha": "saude", "materia": "sus", "assunto": "História", "tipo": "pergunta", "frente": "O que foi o Programa Mais Médicos?", "verso": "Programa de 2013 para provimento de médicos em regiões com carência de profissionais, retomado em 2023.", "explicacao": "Lei 12.871/2013."}, {"id": 2000002801, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "certo_errado", "frente": "Certo ou errado? O SUS pode cobrar por serviços prestados aos usuários.", "verso": "Errado. É vedada a cobrança de qualquer valor do usuário pelos serviços do SUS (gratuidade).", "explicacao": "Lei 8.080/1990, art. 43."}, {"id": 2000002802, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "Planos de saúde devem ressarcir o SUS?", "verso": "Sim, quando seus beneficiários são atendidos em serviços do SUS.", "explicacao": "Lei 9.656/1998, art. 32."}, {"id": 2000002803, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "Qual a forma de participação da iniciativa privada quando a rede pública for insuficiente?", "verso": "Complementar, por contrato ou convênio, seguindo os princípios e normas do SUS.", "explicacao": "Lei 8.080/1990, arts. 24 a 26."}, {"id": 2000002804, "trilha": "saude", "materia": "sus", "assunto": "Controle social", "tipo": "pergunta", "frente": "Qual resolução define as diretrizes para os conselhos de saúde?", "verso": "Resolução CNS 453/2012.", "explicacao": "Os conselhos têm autonomia, reuniões ao menos mensais e dotação orçamentária própria."}, {"id": 2000002805, "trilha": "saude", "materia": "sus", "assunto": "Controle social", "tipo": "pergunta", "frente": "Com que frequência ocorrem as Conferências Nacionais de Saúde?", "verso": "A cada 4 anos.", "explicacao": "A 17ª foi em 2023."}, {"id": 2000002806, "trilha": "saude", "materia": "sus", "assunto": "Financiamento", "tipo": "pergunta", "frente": "Quais os blocos de financiamento do SUS desde 2018?", "verso": "Bloco de Custeio das Ações e Serviços Públicos de Saúde e Bloco de Investimento na Rede de Serviços Públicos de Saúde.", "explicacao": "Portaria MS 3.992/2017. Antes eram seis blocos."}, {"id": 2000002807, "trilha": "saude", "materia": "sus", "assunto": "Saúde digital", "tipo": "pergunta", "frente": "O que é telessaúde?", "verso": "Uso de tecnologias de informação e comunicação para serviços de saúde a distância, como teleconsulta, telediagnóstico e teleducação.", "explicacao": "Lei 14.510/2022."}, {"id": 2000002808, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "Que direito a pessoa com deficiência auditiva tem no SUS para comunicação?", "verso": "Atendimento com intérprete de Libras ou outros recursos de acessibilidade.", "explicacao": "Estatuto da Pessoa com Deficiência."}, {"id": 2000002809, "trilha": "saude", "materia": "sus", "assunto": "Determinantes sociais", "tipo": "pergunta", "frente": "O que são determinantes sociais da saúde?", "verso": "Condições sociais, econômicas, culturais, étnico-raciais, psicológicas e comportamentais que influenciam a ocorrência de problemas de saúde.", "explicacao": "Modelo de Dahlgren e Whitehead."}, {"id": 2000002810, "trilha": "saude", "materia": "sus", "assunto": "Saúde suplementar", "tipo": "pares", "frente": "Sistema público x saúde suplementar.", "verso": "Público: SUS, universal e gratuito. Suplementar: planos e seguros privados regulados pela ANS.", "explicacao": "O Brasil tem sistema misto."}, {"id": 2000002811, "trilha": "saude", "materia": "sus", "assunto": "Atenção especializada", "tipo": "pergunta", "frente": "O que é regulação do acesso no SUS?", "verso": "Organização da oferta de consultas, exames e internações por centrais de regulação, priorizando conforme critérios clínicos.", "explicacao": ""}, {"id": 2000002812, "trilha": "saude", "materia": "sus", "assunto": "Atenção especializada", "tipo": "pergunta", "frente": "O que é o Programa Mais Acesso a Especialistas?", "verso": "Programa de 2024 para reduzir filas de consultas e exames especializados, com ofertas de cuidado integrado.", "explicacao": ""}, {"id": 2000002813, "trilha": "saude", "materia": "sus", "assunto": "Atenção básica", "tipo": "pergunta", "frente": "O que é a Unidade Básica de Saúde (UBS)?", "verso": "Estabelecimento de atenção primária, porta de entrada preferencial do SUS, onde atuam as equipes de atenção básica e saúde da família.", "explicacao": ""}, {"id": 2000002814, "trilha": "saude", "materia": "sus", "assunto": "Atenção básica", "tipo": "pergunta", "frente": "Qual o horário mínimo de funcionamento da UBS segundo a PNAB?", "verso": "40 horas semanais, em pelo menos 5 dias da semana e nos 12 meses do ano.", "explicacao": "PNAB 2017."}, {"id": 2000002815, "trilha": "saude", "materia": "sus", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que é resolubilidade?", "verso": "Capacidade dos serviços de resolver os problemas de saúde no seu nível de complexidade.", "explicacao": "Lei 8.080/1990, art. 7º, XII."}, {"id": 2000002816, "trilha": "saude", "materia": "sus", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que é hierarquização no SUS?", "verso": "Organização dos serviços em níveis crescentes de complexidade (atenção primária, secundária e terciária), com fluxos de referência e contrarreferência.", "explicacao": ""}, {"id": 2000002817, "trilha": "saude", "materia": "sus", "assunto": "Princípios", "tipo": "pares", "frente": "Referência x contrarreferência.", "verso": "Referência: encaminhamento do usuário de um nível de menor para um de maior complexidade. Contrarreferência: retorno ao nível de origem, com informações sobre o atendimento.", "explicacao": ""}, {"id": 2000002818, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "O que é o Sistema Nacional de Sangue, Componentes e Derivados?", "verso": "Sistema coordenado pela direção nacional do SUS, que regula a coleta, processamento e transfusão do sangue, vedada a comercialização.", "explicacao": "Lei 10.205/2001."}, {"id": 2000002819, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "Quem pode doar sangue no Brasil?", "verso": "Pessoas de 16 a 69 anos, com pelo menos 50 kg e em boas condições de saúde (menores de 18 com autorização).", "explicacao": "Primeira doação até 60 anos."}, {"id": 2000002820, "trilha": "saude", "materia": "sus", "assunto": "Políticas", "tipo": "pergunta", "frente": "O que é a Política Nacional de Saúde da Pessoa Idosa?", "verso": "Política que busca recuperar, manter e promover a autonomia e a independência das pessoas idosas.", "explicacao": "Portaria MS 2.528/2006."}, {"id": 2000002821, "trilha": "saude", "materia": "sus", "assunto": "Políticas", "tipo": "pergunta", "frente": "O que é a Política Nacional de Alimentação e Nutrição (PNAN)?", "verso": "Política que visa melhorar as condições de alimentação, nutrição e saúde da população, com vigilância alimentar e promoção da alimentação adequada.", "explicacao": "Guia Alimentar para a População Brasileira recomenda preferir alimentos in natura e evitar ultraprocessados."}, {"id": 2000002822, "trilha": "saude", "materia": "sus", "assunto": "Políticas", "tipo": "pergunta", "frente": "O que é a Política Nacional de Atenção às Urgências?", "verso": "Política que organiza a rede de urgência, com componentes pré-hospitalar fixo e móvel, hospitalar e pós-hospitalar.", "explicacao": "Portaria MS 1.863/2003."}, {"id": 2000002823, "trilha": "saude", "materia": "sus", "assunto": "Políticas", "tipo": "pergunta", "frente": "O que é a Política Nacional de Atenção Oncológica e de Prevenção e Controle do Câncer?", "verso": "Política que organiza a prevenção, o rastreamento, o diagnóstico e o tratamento do câncer no SUS.", "explicacao": "Lei 14.758/2023."}, {"id": 2000002824, "trilha": "saude", "materia": "sus", "assunto": "Lei 12.732", "tipo": "pergunta", "frente": "Em quanto tempo o paciente com câncer deve iniciar o tratamento no SUS?", "verso": "Em até 60 dias do diagnóstico em laudo patológico.", "explicacao": "Lei 12.732/2012. Exames para diagnóstico em até 30 dias (Lei 13.896/2019)."}, {"id": 2000002825, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "pergunta", "frente": "O que é a cadeia epidemiológica?", "verso": "Agente etiológico, reservatório, porta de saída, modo de transmissão, porta de entrada e hospedeiro suscetível.", "explicacao": "Interromper qualquer elo controla a doença."}, {"id": 2000002826, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "pergunta", "frente": "O que é período de incubação?", "verso": "Intervalo entre a exposição ao agente e o surgimento dos sintomas.", "explicacao": "Período de transmissibilidade: quando o agente pode ser transmitido."}, {"id": 2000002827, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "pergunta", "frente": "O que é a tríade epidemiológica?", "verso": "Agente, hospedeiro e ambiente.", "explicacao": ""}, {"id": 2000002828, "trilha": "saude", "materia": "sus", "assunto": "Constituição", "tipo": "pergunta", "frente": "O que a EC 120/2022 garantiu aos agentes comunitários de saúde e de endemias?", "verso": "Piso salarial de dois salários mínimos, pago com assistência financeira da União.", "explicacao": "CF, art. 198, § 9º."}, {"id": 2000002829, "trilha": "saude", "materia": "med", "assunto": "Cardiologia", "tipo": "pergunta", "frente": "Qual o valor de pressão arterial que define hipertensão no consultório (diretriz brasileira)?", "verso": "PA ≥ 140 x 90 mmHg em medidas repetidas, em ocasiões diferentes.", "explicacao": "Abaixo de 120 x 80 mmHg é considerado normal."}, {"id": 2000002830, "trilha": "saude", "materia": "med", "assunto": "Cardiologia", "tipo": "pergunta", "frente": "Quais as classes de anti-hipertensivos de primeira linha?", "verso": "Diuréticos tiazídicos, IECA, BRA e bloqueadores dos canais de cálcio.", "explicacao": "Betabloqueadores em situações específicas."}, {"id": 2000002831, "trilha": "saude", "materia": "med", "assunto": "Cardiologia", "tipo": "pergunta", "frente": "Qual efeito adverso clássico dos IECA (como o captopril)?", "verso": "Tosse seca, além de angioedema e hipercalemia.", "explicacao": "Os BRA (losartana) raramente causam tosse."}, {"id": 2000002832, "trilha": "saude", "materia": "med", "assunto": "Cardiologia", "tipo": "pergunta", "frente": "Qual o marcador laboratorial mais específico para infarto agudo do miocárdio?", "verso": "Troponina.", "explicacao": ""}, {"id": 2000002833, "trilha": "saude", "materia": "med", "assunto": "Cardiologia", "tipo": "pares", "frente": "IAM com supra de ST x sem supra de ST.", "verso": "Com supra: oclusão coronariana total, exige reperfusão imediata (angioplastia primária ou trombolítico). Sem supra: oclusão parcial; estratificação de risco e tratamento antitrombótico.", "explicacao": ""}, {"id": 2000002834, "trilha": "saude", "materia": "med", "assunto": "Cardiologia", "tipo": "pergunta", "frente": "Qual o tempo porta-balão e porta-agulha recomendados no IAM com supra?", "verso": "Porta-balão: até 90 minutos. Porta-agulha (trombólise): até 30 minutos.", "explicacao": ""}, {"id": 2000002835, "trilha": "saude", "materia": "med", "assunto": "Cardiologia", "tipo": "pergunta", "frente": "Qual a primeira medida antiplaquetária na síndrome coronariana aguda?", "verso": "Ácido acetilsalicílico (AAS) mastigado, salvo contraindicação.", "explicacao": ""}, {"id": 2000002836, "trilha": "saude", "materia": "med", "assunto": "Cardiologia", "tipo": "pergunta", "frente": "Qual a arritmia sustentada mais comum na prática clínica?", "verso": "Fibrilação atrial.", "explicacao": "Risco de AVC: anticoagulação conforme o escore CHA₂DS₂-VASc."}, {"id": 2000002837, "trilha": "saude", "materia": "med", "assunto": "Cardiologia", "tipo": "pergunta", "frente": "Quais os sinais da insuficiência cardíaca congestiva esquerda e direita?", "verso": "Esquerda: dispneia, ortopneia, dispneia paroxística noturna, estertores. Direita: edema de membros inferiores, turgência jugular, hepatomegalia, ascite.", "explicacao": ""}, {"id": 2000002838, "trilha": "saude", "materia": "med", "assunto": "Cardiologia", "tipo": "pergunta", "frente": "O que é a tríade de Beck?", "verso": "Hipotensão, turgência jugular e abafamento das bulhas cardíacas, sugestiva de tamponamento cardíaco.", "explicacao": ""}, {"id": 2000002839, "trilha": "saude", "materia": "med", "assunto": "Pneumologia", "tipo": "pergunta", "frente": "Qual o exame que confirma o diagnóstico de DPOC?", "verso": "Espirometria com relação VEF1/CVF < 0,70 após broncodilatador.", "explicacao": "Principal causa: tabagismo."}, {"id": 2000002840, "trilha": "saude", "materia": "med", "assunto": "Pneumologia", "tipo": "pares", "frente": "Asma x DPOC.", "verso": "Asma: obstrução variável e reversível, início geralmente na infância, associada a atopia. DPOC: obstrução persistente e pouco reversível, geralmente após os 40 anos e associada ao tabagismo.", "explicacao": ""}, {"id": 2000002841, "trilha": "saude", "materia": "med", "assunto": "Pneumologia", "tipo": "pergunta", "frente": "Qual o agente mais comum de pneumonia adquirida na comunidade?", "verso": "Streptococcus pneumoniae (pneumococo).", "explicacao": "Escore CURB-65 ajuda a decidir o local de tratamento."}, {"id": 2000002842, "trilha": "saude", "materia": "med", "assunto": "Pneumologia", "tipo": "pergunta", "frente": "O que avalia o escore CURB-65?", "verso": "Confusão, ureia elevada, frequência respiratória ≥ 30, pressão baixa (PAS < 90 ou PAD ≤ 60) e idade ≥ 65 anos.", "explicacao": "0–1: ambulatorial; 2: considerar internação; ≥ 3: grave."}, {"id": 2000002843, "trilha": "saude", "materia": "med", "assunto": "Pneumologia", "tipo": "pergunta", "frente": "Quais os sintomas clássicos da tuberculose pulmonar?", "verso": "Tosse por 3 semanas ou mais, febre vespertina, sudorese noturna, emagrecimento e, às vezes, hemoptise.", "explicacao": "Na população geral, investiga-se o sintomático respiratório com tosse ≥ 3 semanas."}, {"id": 2000002844, "trilha": "saude", "materia": "med", "assunto": "Pneumologia", "tipo": "pergunta", "frente": "Qual o exame inicial de escolha para diagnóstico da tuberculose pulmonar no Brasil?", "verso": "Teste rápido molecular (TRM-TB), quando disponível; senão, baciloscopia de escarro.", "explicacao": "Cultura para casos especiais e teste de sensibilidade."}, {"id": 2000002845, "trilha": "saude", "materia": "med", "assunto": "Pneumologia", "tipo": "pergunta", "frente": "Quais os sinais clínicos do pneumotórax hipertensivo?", "verso": "Dispneia intensa, hipotensão, desvio da traqueia para o lado oposto, turgência jugular e murmúrio vesicular abolido.", "explicacao": "Tratamento imediato: descompressão com agulha."}, {"id": 2000002846, "trilha": "saude", "materia": "med", "assunto": "Pneumologia", "tipo": "pergunta", "frente": "Qual a tríade de Virchow?", "verso": "Estase venosa, lesão endotelial e hipercoagulabilidade.", "explicacao": "Fatores de risco para trombose venosa."}, {"id": 2000002847, "trilha": "saude", "materia": "med", "assunto": "Pneumologia", "tipo": "pergunta", "frente": "Qual o exame de escolha para confirmar embolia pulmonar em paciente estável?", "verso": "Angiotomografia de tórax.", "explicacao": "D-dímero negativo ajuda a afastar em baixo risco."}, {"id": 2000002848, "trilha": "saude", "materia": "med", "assunto": "Endocrinologia", "tipo": "pares", "frente": "Diabetes tipo 1 x tipo 2.", "verso": "Tipo 1: destruição autoimune das células beta, deficiência absoluta de insulina, geralmente em jovens. Tipo 2: resistência à insulina com deficiência relativa, associada a obesidade e sedentarismo.", "explicacao": "O tipo 2 é cerca de 90% dos casos."}, {"id": 2000002849, "trilha": "saude", "materia": "med", "assunto": "Endocrinologia", "tipo": "pergunta", "frente": "Qual o medicamento de primeira linha no diabetes tipo 2?", "verso": "Metformina, junto com mudança de estilo de vida.", "explicacao": "Contraindicada em insuficiência renal grave."}, {"id": 2000002850, "trilha": "saude", "materia": "med", "assunto": "Endocrinologia", "tipo": "pergunta", "frente": "Qual a meta geral de hemoglobina glicada no diabético adulto?", "verso": "Abaixo de 7%, individualizada conforme o paciente.", "explicacao": ""}, {"id": 2000002851, "trilha": "saude", "materia": "med", "assunto": "Endocrinologia", "tipo": "pergunta", "frente": "Quais os critérios da cetoacidose diabética?", "verso": "Hiperglicemia (geralmente > 250 mg/dL), acidose metabólica (pH < 7,3 ou bicarbonato < 18) e cetonemia ou cetonúria.", "explicacao": "Tratamento: hidratação, insulina regular EV e reposição de potássio."}, {"id": 2000002852, "trilha": "saude", "materia": "med", "assunto": "Endocrinologia", "tipo": "pares", "frente": "Hipotireoidismo x hipertireoidismo: sinais.", "verso": "Hipo: cansaço, ganho de peso, intolerância ao frio, constipação, pele seca, bradicardia. Hiper: perda de peso, intolerância ao calor, taquicardia, tremores, ansiedade, diarreia.", "explicacao": "Hashimoto (hipo) e Graves (hiper) são as causas mais comuns."}, {"id": 2000002853, "trilha": "saude", "materia": "med", "assunto": "Endocrinologia", "tipo": "pergunta", "frente": "Qual o exame inicial para avaliar a função da tireoide?", "verso": "TSH.", "explicacao": "TSH alto com T4 livre baixo: hipotireoidismo primário."}, {"id": 2000002854, "trilha": "saude", "materia": "med", "assunto": "Endocrinologia", "tipo": "pergunta", "frente": "Como se classifica a obesidade pelo IMC?", "verso": "Sobrepeso: 25 a 29,9. Obesidade grau I: 30 a 34,9. Grau II: 35 a 39,9. Grau III: ≥ 40 kg/m².", "explicacao": "IMC = peso ÷ altura²."}, {"id": 2000002855, "trilha": "saude", "materia": "med", "assunto": "Gastroenterologia", "tipo": "pergunta", "frente": "Qual a causa mais comum de úlcera péptica?", "verso": "Infecção por Helicobacter pylori, seguida do uso de anti-inflamatórios não esteroides.", "explicacao": ""}, {"id": 2000002856, "trilha": "saude", "materia": "med", "assunto": "Gastroenterologia", "tipo": "pergunta", "frente": "Quais os sinais típicos de apendicite aguda?", "verso": "Dor que começa na região periumbilical e migra para a fossa ilíaca direita, anorexia, náuseas, febre e sinal de Blumberg positivo.", "explicacao": "Ponto de McBurney."}, {"id": 2000002857, "trilha": "saude", "materia": "med", "assunto": "Gastroenterologia", "tipo": "pergunta", "frente": "O que é o sinal de Murphy?", "verso": "Interrupção da inspiração ao palpar o ponto cístico (hipocôndrio direito); sugere colecistite aguda.", "explicacao": ""}, {"id": 2000002858, "trilha": "saude", "materia": "med", "assunto": "Gastroenterologia", "tipo": "pergunta", "frente": "Quais as causas mais comuns de pancreatite aguda?", "verso": "Litíase biliar e álcool.", "explicacao": "Amilase e lipase elevadas (3 vezes o limite)."}, {"id": 2000002859, "trilha": "saude", "materia": "med", "assunto": "Gastroenterologia", "tipo": "pares", "frente": "Hepatite A x B x C: transmissão.", "verso": "A: fecal-oral, aguda, não cronifica. B: sexual, sangue e vertical; pode cronificar; tem vacina. C: principalmente sangue; cronifica com frequência; tem cura com antivirais, sem vacina.", "explicacao": ""}, {"id": 2000002860, "trilha": "saude", "materia": "med", "assunto": "Gastroenterologia", "tipo": "pergunta", "frente": "O que significa HBsAg positivo?", "verso": "Presença do vírus da hepatite B (infecção aguda ou crônica).", "explicacao": "Anti-HBs isolado positivo indica imunidade (vacina)."}, {"id": 2000002861, "trilha": "saude", "materia": "med", "assunto": "Gastroenterologia", "tipo": "pergunta", "frente": "Quais as complicações da cirrose hepática?", "verso": "Ascite, varizes esofágicas com sangramento, encefalopatia hepática, peritonite bacteriana espontânea e carcinoma hepatocelular.", "explicacao": ""}, {"id": 2000002862, "trilha": "saude", "materia": "med", "assunto": "Nefrologia", "tipo": "pergunta", "frente": "Como se estadia a doença renal crônica?", "verso": "Pela taxa de filtração glomerular: estágio 1 (≥ 90) até estágio 5 (< 15 mL/min/1,73 m²), com albuminúria.", "explicacao": "Principais causas: diabetes e hipertensão."}, {"id": 2000002863, "trilha": "saude", "materia": "med", "assunto": "Nefrologia", "tipo": "pergunta", "frente": "Quais as indicações de diálise de urgência?", "verso": "Acidose grave, distúrbios eletrolíticos graves (hipercalemia), intoxicações, hipervolemia refratária e uremia sintomática (pericardite, encefalopatia).", "explicacao": "Mnemônico AEIOU."}, {"id": 2000002864, "trilha": "saude", "materia": "med", "assunto": "Nefrologia", "tipo": "pergunta", "frente": "Qual a alteração eletrocardiográfica clássica da hipercalemia?", "verso": "Onda T apiculada (em tenda), podendo evoluir com alargamento do QRS.", "explicacao": "Tratamento: gluconato de cálcio para estabilizar a membrana."}, {"id": 2000002865, "trilha": "saude", "materia": "med", "assunto": "Neurologia", "tipo": "pares", "frente": "AVC isquêmico x hemorrágico.", "verso": "Isquêmico: obstrução arterial (cerca de 85% dos casos). Hemorrágico: rompimento de vaso. A tomografia sem contraste diferencia os dois.", "explicacao": "Trombólise só no isquêmico, em até 4,5 h."}, {"id": 2000002866, "trilha": "saude", "materia": "med", "assunto": "Neurologia", "tipo": "pergunta", "frente": "O que é AIT (ataque isquêmico transitório)?", "verso": "Déficit neurológico transitório por isquemia, sem infarto no exame de imagem, geralmente com duração menor que 1 hora.", "explicacao": "Sinal de alto risco de AVC."}, {"id": 2000002867, "trilha": "saude", "materia": "med", "assunto": "Neurologia", "tipo": "pergunta", "frente": "Qual a conduta inicial na crise convulsiva prolongada?", "verso": "Proteger o paciente, posição lateral, oxigênio e benzodiazepínico (como diazepam ou midazolam) se durar mais de 5 minutos.", "explicacao": "Estado de mal epiléptico: crise ≥ 5 min ou crises repetidas sem recuperação."}, {"id": 2000002868, "trilha": "saude", "materia": "med", "assunto": "Neurologia", "tipo": "pergunta", "frente": "Quais os sinais de irritação meníngea?", "verso": "Rigidez de nuca, sinais de Kernig e Brudzinski.", "explicacao": "Meningite bacteriana: febre, cefaleia, vômitos, rigidez de nuca."}, {"id": 2000002869, "trilha": "saude", "materia": "med", "assunto": "Neurologia", "tipo": "pergunta", "frente": "Quais os sinais cardinais da doença de Parkinson?", "verso": "Tremor de repouso, rigidez, bradicinesia e instabilidade postural.", "explicacao": ""}, {"id": 2000002870, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "Quais os critérios de sepse atualmente (Sepsis-3)?", "verso": "Disfunção orgânica ameaçadora à vida causada por resposta desregulada à infecção (aumento de 2 ou mais pontos no SOFA).", "explicacao": "qSOFA à beira do leito: FR ≥ 22, alteração mental, PAS ≤ 100."}, {"id": 2000002871, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "O que é o choque séptico?", "verso": "Sepse com necessidade de vasopressor para manter PAM ≥ 65 mmHg e lactato > 2 mmol/L, apesar de reposição volêmica adequada.", "explicacao": "Sepsis-3."}, {"id": 2000002872, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "Quais as medidas da primeira hora na sepse?", "verso": "Coletar lactato e hemoculturas, iniciar antibiótico de amplo espectro, cristaloide 30 mL/kg se hipotensão ou lactato ≥ 4 e vasopressor se necessário.", "explicacao": "Bundle da Surviving Sepsis Campaign."}, {"id": 2000002873, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "Qual o tratamento da sífilis primária, secundária ou latente recente?", "verso": "Penicilina benzatina 2,4 milhões UI IM, dose única.", "explicacao": "Latente tardia ou desconhecida: 3 doses semanais (7,2 milhões UI)."}, {"id": 2000002874, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "Qual o exame de rastreamento e o de confirmação da sífilis?", "verso": "Testes treponêmicos (teste rápido, FTA-Abs) e não treponêmicos (VDRL), que se complementam; o VDRL é usado para acompanhar o tratamento.", "explicacao": ""}, {"id": 2000002875, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "O que é a PEP para HIV?", "verso": "Profilaxia pós-exposição com antirretrovirais, iniciada o mais rápido possível (até 72 horas) e mantida por 28 dias.", "explicacao": ""}, {"id": 2000002876, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "O que é a PrEP?", "verso": "Profilaxia pré-exposição ao HIV, com uso de antirretrovirais por pessoas com maior risco de infecção.", "explicacao": "Oferecida pelo SUS."}, {"id": 2000002877, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "O que significa “indetectável = intransmissível” no HIV?", "verso": "Pessoas com carga viral indetectável há pelo menos 6 meses não transmitem o HIV por via sexual.", "explicacao": ""}, {"id": 2000002878, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "Quais as fases clínicas da dengue?", "verso": "Febril, crítica (na defervescência, com risco de extravasamento plasmático) e de recuperação.", "explicacao": ""}, {"id": 2000002879, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "Qual analgésico deve ser evitado na suspeita de dengue?", "verso": "Ácido acetilsalicílico e anti-inflamatórios não esteroides, pelo risco de sangramento.", "explicacao": "Usa-se dipirona ou paracetamol."}, {"id": 2000002880, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "Qual o agente e o vetor da leishmaniose visceral?", "verso": "Leishmania infantum (chagasi), transmitida pelo flebotomíneo (mosquito-palha).", "explicacao": "O cão é o principal reservatório urbano."}, {"id": 2000002881, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "Como se transmite a raiva e qual a conduta após mordedura?", "verso": "Saliva de mamífero infectado; lavar o ferimento com água e sabão e avaliar profilaxia com vacina e soro/imunoglobulina conforme o animal e a lesão.", "explicacao": "Doença quase sempre fatal após sintomas."}, {"id": 2000002882, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "Qual a profilaxia do tétano em ferimentos?", "verso": "Depende da história vacinal e do tipo de ferimento: vacina (dT) e, em ferimentos de risco com vacinação incompleta, soro ou imunoglobulina antitetânica.", "explicacao": ""}, {"id": 2000002883, "trilha": "saude", "materia": "med", "assunto": "Hematologia", "tipo": "pares", "frente": "Anemia microcítica x macrocítica.", "verso": "Microcítica (VCM baixo): deficiência de ferro, talassemias. Macrocítica (VCM alto): deficiência de B12 ou ácido fólico, álcool, hepatopatia.", "explicacao": "A anemia ferropriva é a mais comum."}, {"id": 2000002884, "trilha": "saude", "materia": "med", "assunto": "Hematologia", "tipo": "pergunta", "frente": "Qual exame avalia melhor os estoques de ferro?", "verso": "Ferritina.", "explicacao": "Baixa na anemia ferropriva."}, {"id": 2000002885, "trilha": "saude", "materia": "med", "assunto": "Hematologia", "tipo": "pergunta", "frente": "Qual a herança e a alteração da anemia falciforme?", "verso": "Autossômica recessiva, por mutação na hemoglobina (HbS), que deforma as hemácias em foice em baixa oxigenação.", "explicacao": "Detectada no teste do pezinho."}, {"id": 2000002886, "trilha": "saude", "materia": "med", "assunto": "Hematologia", "tipo": "pergunta", "frente": "Qual exame monitora a anticoagulação com varfarina?", "verso": "O INR (tempo de protrombina), com alvo geralmente entre 2 e 3.", "explicacao": "Heparina não fracionada: TTPa."}, {"id": 2000002887, "trilha": "saude", "materia": "med", "assunto": "Reumatologia", "tipo": "pergunta", "frente": "Qual o critério de artrite reumatoide quanto às articulações típicas?", "verso": "Poliartrite simétrica de pequenas articulações das mãos e pés, com rigidez matinal prolongada (mais de 1 hora).", "explicacao": "Fator reumatoide e anti-CCP."}, {"id": 2000002888, "trilha": "saude", "materia": "med", "assunto": "Reumatologia", "tipo": "pergunta", "frente": "Qual a causa e as articulações típicas da gota?", "verso": "Depósito de cristais de urato monossódico por hiperuricemia; acomete classicamente a primeira articulação metatarsofalangiana (podagra).", "explicacao": ""}, {"id": 2000002889, "trilha": "saude", "materia": "med", "assunto": "Saúde da mulher", "tipo": "pergunta", "frente": "Qual vírus causa o câncer do colo do útero?", "verso": "O papilomavírus humano (HPV), especialmente os tipos 16 e 18.", "explicacao": "Vacina HPV no SUS para meninos e meninas de 9 a 14 anos, em dose única."}, {"id": 2000002890, "trilha": "saude", "materia": "med", "assunto": "Saúde da mulher", "tipo": "pergunta", "frente": "Qual a principal causa de morte materna no Brasil?", "verso": "Síndromes hipertensivas da gestação, seguidas de hemorragias e infecções.", "explicacao": "Causas obstétricas diretas."}, {"id": 2000002891, "trilha": "saude", "materia": "med", "assunto": "Saúde da mulher", "tipo": "pergunta", "frente": "Qual o critério de diabetes gestacional pelo teste oral de tolerância à glicose (75 g)?", "verso": "Jejum ≥ 92, 1 hora ≥ 180 ou 2 horas ≥ 153 mg/dL (basta um valor).", "explicacao": "Feito entre 24 e 28 semanas."}, {"id": 2000002892, "trilha": "saude", "materia": "med", "assunto": "Saúde da mulher", "tipo": "pares", "frente": "Placenta prévia x descolamento prematuro de placenta.", "verso": "Placenta prévia: sangramento indolor, vermelho vivo, de repetição. Descolamento prematuro: sangramento escuro com dor e útero hipertônico, ligado à hipertensão.", "explicacao": "Ambos no 3º trimestre."}, {"id": 2000002893, "trilha": "saude", "materia": "med", "assunto": "Pediatria", "tipo": "pergunta", "frente": "Quais os marcos motores do primeiro ano de vida?", "verso": "Sustenta a cabeça por volta de 3 meses, senta sem apoio por volta de 6 a 8 meses e anda por volta de 12 meses.", "explicacao": "Há variação normal entre crianças."}, {"id": 2000002894, "trilha": "saude", "materia": "med", "assunto": "Pediatria", "tipo": "pergunta", "frente": "Qual o agente mais comum da bronquiolite?", "verso": "Vírus sincicial respiratório (VSR).", "explicacao": "Acomete menores de 2 anos; tratamento de suporte."}, {"id": 2000002895, "trilha": "saude", "materia": "med", "assunto": "Pediatria", "tipo": "pergunta", "frente": "Quais os sinais de gravidade na criança com pneumonia (AIDPI)?", "verso": "Tiragem subcostal, estridor em repouso, incapacidade de beber, convulsões, letargia e vômitos de tudo.", "explicacao": "Indicam referência urgente."}, {"id": 2000002896, "trilha": "saude", "materia": "med", "assunto": "Pediatria", "tipo": "pergunta", "frente": "Qual a frequência respiratória que define taquipneia por faixa etária na criança?", "verso": "Menor de 2 meses: ≥ 60; de 2 a 11 meses: ≥ 50; de 1 a 4 anos: ≥ 40 irpm.", "explicacao": "AIDPI."}, {"id": 2000002897, "trilha": "saude", "materia": "med", "assunto": "Pediatria", "tipo": "pergunta", "frente": "Qual a solução indicada na terapia de reidratação oral?", "verso": "Sais de reidratação oral (soro de baixa osmolaridade), em pequenas quantidades frequentes.", "explicacao": "Zinco por 10 a 14 dias na diarreia aguda infantil."}, {"id": 2000002898, "trilha": "saude", "materia": "med", "assunto": "Saúde mental", "tipo": "pergunta", "frente": "Quais os critérios principais do episódio depressivo?", "verso": "Humor deprimido ou perda de interesse/prazer (anedonia) na maior parte do dia, quase todos os dias, por pelo menos 2 semanas, com outros sintomas.", "explicacao": "DSM-5."}, {"id": 2000002899, "trilha": "saude", "materia": "med", "assunto": "Saúde mental", "tipo": "pergunta", "frente": "Qual a classe de antidepressivos mais usada na atenção primária?", "verso": "Inibidores seletivos da recaptação de serotonina (ISRS), como fluoxetina e sertralina.", "explicacao": "Efeito pleno em 4 a 6 semanas."}, {"id": 2000002900, "trilha": "saude", "materia": "med", "assunto": "Saúde mental", "tipo": "pergunta", "frente": "Qual o principal efeito adverso a monitorar no uso de lítio?", "verso": "Toxicidade (janela terapêutica estreita): tremor, náusea, confusão; monitorar litemia, função renal e tireoidiana.", "explicacao": ""}, {"id": 2000002901, "trilha": "saude", "materia": "med", "assunto": "Saúde mental", "tipo": "pergunta", "frente": "Quais os sintomas da abstinência alcoólica grave (delirium tremens)?", "verso": "Confusão, alucinações (principalmente visuais), agitação, tremores, febre e taquicardia, cerca de 48 a 72 horas após a última dose.", "explicacao": "Tratamento com benzodiazepínicos e tiamina."}, {"id": 2000002902, "trilha": "saude", "materia": "med", "assunto": "Saúde mental", "tipo": "pergunta", "frente": "Por que se dá tiamina antes da glicose no paciente etilista?", "verso": "Para prevenir a encefalopatia de Wernicke.", "explicacao": "Tríade: confusão, ataxia e oftalmoplegia."}, {"id": 2000002903, "trilha": "saude", "materia": "med", "assunto": "Farmacologia", "tipo": "pergunta", "frente": "Qual o principal risco do uso crônico de anti-inflamatórios não esteroides?", "verso": "Lesão gastrointestinal (úlcera e sangramento), lesão renal e aumento de risco cardiovascular.", "explicacao": ""}, {"id": 2000002904, "trilha": "saude", "materia": "med", "assunto": "Farmacologia", "tipo": "pergunta", "frente": "Qual o efeito adverso grave da intoxicação por paracetamol e o antídoto?", "verso": "Hepatotoxicidade (necrose hepática); antídoto: N-acetilcisteína.", "explicacao": ""}, {"id": 2000002905, "trilha": "saude", "materia": "med", "assunto": "Farmacologia", "tipo": "pergunta", "frente": "Quais as manifestações e o tratamento da anafilaxia?", "verso": "Urticária, angioedema, broncoespasmo, hipotensão; tratamento imediato com adrenalina intramuscular (0,5 mg no adulto, na face anterolateral da coxa).", "explicacao": "Anti-histamínicos e corticoides são adjuvantes."}, {"id": 2000002906, "trilha": "saude", "materia": "med", "assunto": "Farmacologia", "tipo": "pergunta", "frente": "Quais medicamentos exigem receita de controle especial (Portaria 344/1998)?", "verso": "Entorpecentes, psicotrópicos, retinoides e outros das listas da portaria.", "explicacao": "Notificação de receita A (amarela), B (azul) e especial."}, {"id": 2000002907, "trilha": "saude", "materia": "med", "assunto": "Farmacologia", "tipo": "pares", "frente": "Receita amarela (A) x azul (B) x branca de controle especial.", "verso": "A: entorpecentes (morfina, metadona). B: psicotrópicos (benzodiazepínicos). Branca em duas vias: outras substâncias controladas (antidepressivos, anticonvulsivantes).", "explicacao": "Portaria SVS/MS 344/1998."}, {"id": 2000002908, "trilha": "saude", "materia": "med", "assunto": "Trauma", "tipo": "pergunta", "frente": "Qual a principal causa de morte evitável no trauma?", "verso": "Hemorragia.", "explicacao": "Por isso o XABCDE começa pelo controle de hemorragia exsanguinante."}, {"id": 2000002909, "trilha": "saude", "materia": "med", "assunto": "Trauma", "tipo": "pares", "frente": "Classes de choque hemorrágico (ATLS).", "verso": "Classe I: perda até 15%. Classe II: 15% a 30%. Classe III: 30% a 40% (hipotensão). Classe IV: mais de 40%.", "explicacao": ""}, {"id": 2000002910, "trilha": "saude", "materia": "med", "assunto": "Trauma", "tipo": "pergunta", "frente": "O que é o trauma raquimedular e como se imobiliza?", "verso": "Lesão da medula espinhal; imobilização com colar cervical e prancha ou técnicas de restrição de movimento da coluna conforme protocolo.", "explicacao": ""}, {"id": 2000002911, "trilha": "saude", "materia": "med", "assunto": "Terapia intensiva", "tipo": "pergunta", "frente": "Qual a pressão arterial média alvo no choque séptico?", "verso": "PAM ≥ 65 mmHg.", "explicacao": "Noradrenalina é o vasopressor de primeira escolha."}, {"id": 2000002912, "trilha": "saude", "materia": "med", "assunto": "Terapia intensiva", "tipo": "pergunta", "frente": "O que é a escala de RASS?", "verso": "Escala de agitação e sedação de Richmond, de +4 (combativo) a −5 (sem resposta).", "explicacao": ""}, {"id": 2000002913, "trilha": "saude", "materia": "med", "assunto": "Ética médica", "tipo": "pergunta", "frente": "Qual resolução aprova o Código de Ética Médica vigente?", "verso": "Resolução CFM 2.217/2018.", "explicacao": ""}, {"id": 2000002914, "trilha": "saude", "materia": "med", "assunto": "Ética médica", "tipo": "pergunta", "frente": "O médico pode revelar fato sigiloso de que tenha conhecimento?", "verso": "Não, salvo por motivo justo, dever legal ou consentimento por escrito do paciente.", "explicacao": "Código de Ética Médica, art. 73."}, {"id": 2000002915, "trilha": "saude", "materia": "med", "assunto": "Ética médica", "tipo": "pergunta", "frente": "Quem deve emitir a declaração de óbito em morte natural com assistência médica?", "verso": "O médico que vinha prestando assistência ao paciente.", "explicacao": "Morte violenta: IML."}, {"id": 2000002916, "trilha": "saude", "materia": "med", "assunto": "Ética médica", "tipo": "pergunta", "frente": "Em morte natural sem assistência médica em local sem SVO, quem emite a declaração de óbito?", "verso": "O médico do serviço público de saúde mais próximo ou, na falta, qualquer médico da localidade.", "explicacao": ""}, {"id": 2000002917, "trilha": "saude", "materia": "med", "assunto": "Saúde pública", "tipo": "pergunta", "frente": "Qual a principal causa de morte no Brasil?", "verso": "Doenças do aparelho circulatório (cardiovasculares).", "explicacao": "Seguidas de neoplasias."}, {"id": 2000002918, "trilha": "saude", "materia": "med", "assunto": "Saúde pública", "tipo": "pergunta", "frente": "Quais os fatores de risco modificáveis mais importantes para doenças cardiovasculares?", "verso": "Hipertensão, tabagismo, diabetes, dislipidemia, obesidade, sedentarismo e alimentação inadequada.", "explicacao": ""}, {"id": 2000002919, "trilha": "saude", "materia": "med", "assunto": "Saúde pública", "tipo": "pergunta", "frente": "O que é o rastreamento?", "verso": "Realização de exames em pessoas assintomáticas para detectar doença precocemente.", "explicacao": "Exige doença relevante, fase pré-clínica detectável e tratamento eficaz."}, {"id": 2000002920, "trilha": "saude", "materia": "med", "assunto": "Exames", "tipo": "pergunta", "frente": "Qual a glicemia de jejum normal?", "verso": "Abaixo de 100 mg/dL.", "explicacao": "100 a 125: glicemia de jejum alterada (pré-diabetes)."}, {"id": 2000002921, "trilha": "saude", "materia": "med", "assunto": "Exames", "tipo": "pergunta", "frente": "Qual o LDL-colesterol alvo em pacientes de muito alto risco cardiovascular?", "verso": "Abaixo de 50 mg/dL.", "explicacao": "Metas variam conforme o risco."}, {"id": 2000002922, "trilha": "saude", "materia": "med", "assunto": "Exames", "tipo": "pergunta", "frente": "Qual o valor normal do potássio sérico?", "verso": "Entre 3,5 e 5,0 mEq/L.", "explicacao": "Sódio: 135 a 145 mEq/L."}, {"id": 2000002923, "trilha": "saude", "materia": "med", "assunto": "Exames", "tipo": "pergunta", "frente": "O que avalia a gasometria arterial?", "verso": "pH, PaO₂, PaCO₂, bicarbonato, excesso de bases e saturação, para avaliar oxigenação e equilíbrio ácido-básico.", "explicacao": "pH normal: 7,35 a 7,45."}, {"id": 2000002924, "trilha": "saude", "materia": "med", "assunto": "Exames", "tipo": "pares", "frente": "Acidose respiratória x metabólica.", "verso": "Respiratória: pH baixo com PaCO₂ alta (hipoventilação). Metabólica: pH baixo com bicarbonato baixo (cetoacidose, diarreia, insuficiência renal).", "explicacao": ""}, {"id": 2000002925, "trilha": "saude", "materia": "med", "assunto": "Exames", "tipo": "pergunta", "frente": "O que indica leucocitose com desvio à esquerda?", "verso": "Aumento de formas jovens de neutrófilos (bastões), sugestivo de infecção bacteriana aguda.", "explicacao": ""}, {"id": 2000002926, "trilha": "saude", "materia": "med", "assunto": "Dermatologia", "tipo": "pergunta", "frente": "Qual a regra ABCDE para lesões suspeitas de melanoma?", "verso": "Assimetria, Bordas irregulares, Cor variada, Diâmetro > 6 mm e Evolução (mudança).", "explicacao": ""}, {"id": 2000002927, "trilha": "saude", "materia": "med", "assunto": "Oftalmologia", "tipo": "pergunta", "frente": "O que é glaucoma?", "verso": "Neuropatia óptica, geralmente associada a aumento da pressão intraocular, com perda progressiva do campo visual.", "explicacao": "Principal causa de cegueira irreversível."}, {"id": 2000002928, "trilha": "saude", "materia": "med", "assunto": "Urologia", "tipo": "pergunta", "frente": "Quais os sintomas da hiperplasia prostática benigna?", "verso": "Jato urinário fraco, hesitação, gotejamento, nictúria, sensação de esvaziamento incompleto e urgência.", "explicacao": ""}, {"id": 2000002929, "trilha": "saude", "materia": "med", "assunto": "Geriatria", "tipo": "pergunta", "frente": "O que é polifarmácia e por que é um problema no idoso?", "verso": "Uso de 5 ou mais medicamentos; aumenta interações, efeitos adversos, quedas e confusão.", "explicacao": "Critérios de Beers listam medicamentos inapropriados para idosos."}, {"id": 2000002930, "trilha": "saude", "materia": "fisio", "assunto": "Exercício profissional", "tipo": "pergunta", "frente": "Qual decreto-lei cria as profissões de fisioterapeuta e terapeuta ocupacional?", "verso": "Decreto-Lei 938/1969.", "explicacao": ""}, {"id": 2000002931, "trilha": "saude", "materia": "fisio", "assunto": "Exercício profissional", "tipo": "pergunta", "frente": "Qual o órgão que fiscaliza a fisioterapia?", "verso": "O Sistema Coffito/Crefito (Conselho Federal e Conselhos Regionais de Fisioterapia e Terapia Ocupacional).", "explicacao": "Lei 6.316/1975."}, {"id": 2000002932, "trilha": "saude", "materia": "fisio", "assunto": "Exercício profissional", "tipo": "pergunta", "frente": "O fisioterapeuta pode dar diagnóstico?", "verso": "Sim, o diagnóstico cinesiológico funcional, e prescrever, executar e dar alta do tratamento fisioterapêutico.", "explicacao": "Resolução Coffito 80/1987."}, {"id": 2000002933, "trilha": "saude", "materia": "fisio", "assunto": "Exercício profissional", "tipo": "pergunta", "frente": "Qual resolução aprova o Código de Ética e Deontologia da Fisioterapia?", "verso": "Resolução Coffito 424/2013.", "explicacao": ""}, {"id": 2000002934, "trilha": "saude", "materia": "fisio", "assunto": "Avaliação", "tipo": "pergunta", "frente": "O que avalia a goniometria?", "verso": "A amplitude de movimento articular, em graus.", "explicacao": ""}, {"id": 2000002935, "trilha": "saude", "materia": "fisio", "assunto": "Avaliação", "tipo": "pergunta", "frente": "Como se gradua a força muscular na escala de Oxford (MRC)?", "verso": "0: sem contração; 1: contração sem movimento; 2: movimento sem gravidade; 3: vence a gravidade; 4: vence alguma resistência; 5: força normal.", "explicacao": ""}, {"id": 2000002936, "trilha": "saude", "materia": "fisio", "assunto": "Avaliação", "tipo": "pergunta", "frente": "Qual escala avalia a espasticidade?", "verso": "Escala de Ashworth modificada.", "explicacao": "Graus 0, 1, 1+, 2, 3 e 4."}, {"id": 2000002937, "trilha": "saude", "materia": "fisio", "assunto": "Avaliação", "tipo": "pergunta", "frente": "Qual escala avalia o equilíbrio em idosos e o risco de quedas?", "verso": "Escala de Equilíbrio de Berg.", "explicacao": "Pontuação máxima de 56."}, {"id": 2000002938, "trilha": "saude", "materia": "fisio", "assunto": "Avaliação", "tipo": "pergunta", "frente": "O que é o teste Timed Up and Go (TUG)?", "verso": "O paciente levanta da cadeira, caminha 3 metros, volta e senta; tempo elevado indica risco de quedas e menor mobilidade.", "explicacao": ""}, {"id": 2000002939, "trilha": "saude", "materia": "fisio", "assunto": "Avaliação", "tipo": "pergunta", "frente": "O que mede o índice de Barthel?", "verso": "A independência nas atividades básicas de vida diária.", "explicacao": "Índice de Katz também avalia AVDs básicas; Lawton, as instrumentais."}, {"id": 2000002940, "trilha": "saude", "materia": "fisio", "assunto": "Avaliação", "tipo": "pergunta", "frente": "Para que serve o teste de caminhada de 6 minutos?", "verso": "Avaliar a capacidade funcional ao exercício, principalmente em doenças cardiorrespiratórias.", "explicacao": ""}, {"id": 2000002941, "trilha": "saude", "materia": "fisio", "assunto": "Avaliação", "tipo": "pergunta", "frente": "O que é a CIF?", "verso": "Classificação Internacional de Funcionalidade, Incapacidade e Saúde (OMS), que descreve funções e estruturas do corpo, atividades e participação e fatores ambientais.", "explicacao": "Modelo biopsicossocial."}, {"id": 2000002942, "trilha": "saude", "materia": "fisio", "assunto": "Cinesiologia", "tipo": "pares", "frente": "Movimento de flexão x extensão x abdução x adução.", "verso": "Flexão: diminui o ângulo articular. Extensão: aumenta o ângulo. Abdução: afasta da linha média. Adução: aproxima da linha média.", "explicacao": ""}, {"id": 2000002943, "trilha": "saude", "materia": "fisio", "assunto": "Cinesiologia", "tipo": "pares", "frente": "Contração concêntrica x excêntrica x isométrica.", "verso": "Concêntrica: o músculo encurta. Excêntrica: o músculo alonga sob tensão. Isométrica: tensão sem mudança de comprimento.", "explicacao": "A excêntrica gera mais força e mais dor muscular tardia."}, {"id": 2000002944, "trilha": "saude", "materia": "fisio", "assunto": "Cinesiologia", "tipo": "pares", "frente": "Cadeia cinética aberta x fechada.", "verso": "Aberta: segmento distal livre (extensora de joelho). Fechada: segmento distal fixo (agachamento).", "explicacao": "A fechada costuma ser usada no pós-operatório do LCA."}, {"id": 2000002945, "trilha": "saude", "materia": "fisio", "assunto": "Cinesiologia", "tipo": "pares", "frente": "Músculo agonista x antagonista x sinergista.", "verso": "Agonista: principal responsável pelo movimento. Antagonista: realiza o movimento oposto. Sinergista: auxilia o agonista.", "explicacao": ""}, {"id": 2000002946, "trilha": "saude", "materia": "fisio", "assunto": "Cinesiologia", "tipo": "pergunta", "frente": "Quais os músculos do manguito rotador?", "verso": "Supraespinal, infraespinal, redondo menor e subescapular.", "explicacao": "O supraespinal é o mais lesionado."}, {"id": 2000002947, "trilha": "saude", "materia": "fisio", "assunto": "Cinesiologia", "tipo": "pergunta", "frente": "Quais as fases da marcha?", "verso": "Fase de apoio (cerca de 60% do ciclo) e fase de balanço (cerca de 40%).", "explicacao": ""}, {"id": 2000002948, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "Qual a função do ligamento cruzado anterior?", "verso": "Impedir a anteriorização da tíbia em relação ao fêmur e controlar a rotação.", "explicacao": "Teste de Lachman e gaveta anterior."}, {"id": 2000002949, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "O que avalia o teste de McMurray?", "verso": "Lesão de menisco.", "explicacao": ""}, {"id": 2000002950, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "O que avalia o teste de Phalen?", "verso": "Síndrome do túnel do carpo (compressão do nervo mediano).", "explicacao": "Tinel também é usado."}, {"id": 2000002951, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "O que avalia o teste de Lasègue?", "verso": "Compressão de raiz nervosa lombar (ciatalgia), pela elevação da perna estendida.", "explicacao": "Positivo com dor irradiada entre 30° e 70°."}, {"id": 2000002952, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "O que avalia o teste de Neer e de Hawkins?", "verso": "Impacto subacromial do ombro.", "explicacao": ""}, {"id": 2000002953, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "O que avalia o teste de Finkelstein?", "verso": "Tenossinovite de De Quervain (abdutor longo e extensor curto do polegar).", "explicacao": ""}, {"id": 2000002954, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "O que é o protocolo PRICE (ou POLICE) em lesões agudas?", "verso": "Proteção, repouso (ou carga ótima), gelo, compressão e elevação.", "explicacao": "Nos primeiros dias da lesão."}, {"id": 2000002955, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "Quanto tempo se aplica crioterapia em lesões agudas?", "verso": "Em geral de 15 a 20 minutos, com proteção da pele.", "explicacao": ""}, {"id": 2000002956, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pares", "frente": "Entorse x luxação x subluxação.", "verso": "Entorse: lesão ligamentar por movimento além do limite. Luxação: perda total do contato entre as superfícies articulares. Subluxação: perda parcial.", "explicacao": ""}, {"id": 2000002957, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "Qual a postura típica da escoliose e como se avalia?", "verso": "Desvio lateral da coluna com rotação vertebral; avaliação pelo teste de Adams e ângulo de Cobb na radiografia.", "explicacao": ""}, {"id": 2000002958, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pares", "frente": "Hipercifose x hiperlordose.", "verso": "Hipercifose: aumento da curvatura torácica (convexidade posterior). Hiperlordose: aumento da curvatura lombar ou cervical (concavidade posterior).", "explicacao": ""}, {"id": 2000002959, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "Quais os cuidados após artroplastia total de quadril por via posterior?", "verso": "Evitar flexão acima de 90°, adução além da linha média e rotação interna do quadril operado.", "explicacao": "Risco de luxação da prótese."}, {"id": 2000002960, "trilha": "saude", "materia": "fisio", "assunto": "Neurologia", "tipo": "pares", "frente": "Lesão de neurônio motor superior x inferior.", "verso": "Superior: espasticidade, hiper-reflexia, sinal de Babinski. Inferior: flacidez, hiporreflexia, atrofia e fasciculações.", "explicacao": ""}, {"id": 2000002961, "trilha": "saude", "materia": "fisio", "assunto": "Neurologia", "tipo": "pergunta", "frente": "Qual o padrão postural típico do hemiplégico pós-AVC?", "verso": "Membro superior em flexão, adução e rotação interna; membro inferior em extensão, com pé equino e marcha ceifante.", "explicacao": "Padrão de Wernicke-Mann."}, {"id": 2000002962, "trilha": "saude", "materia": "fisio", "assunto": "Neurologia", "tipo": "pergunta", "frente": "O que é o conceito Bobath?", "verso": "Abordagem neuroevolutiva que busca inibir padrões anormais e facilitar movimentos normais em lesões do sistema nervoso central.", "explicacao": ""}, {"id": 2000002963, "trilha": "saude", "materia": "fisio", "assunto": "Neurologia", "tipo": "pergunta", "frente": "O que é a facilitação neuromuscular proprioceptiva (FNP/Kabat)?", "verso": "Técnica que usa padrões diagonais e espirais de movimento e estímulos proprioceptivos para melhorar força, coordenação e amplitude.", "explicacao": ""}, {"id": 2000002964, "trilha": "saude", "materia": "fisio", "assunto": "Neurologia", "tipo": "pergunta", "frente": "O que é a terapia por contensão induzida?", "verso": "Restrição do membro sadio para forçar o uso do membro afetado, explorando a neuroplasticidade no pós-AVC.", "explicacao": ""}, {"id": 2000002965, "trilha": "saude", "materia": "fisio", "assunto": "Neurologia", "tipo": "pares", "frente": "Paralisia cerebral espástica x discinética x atáxica.", "verso": "Espástica: aumento do tônus (forma mais comum). Discinética: movimentos involuntários (atetose, distonia). Atáxica: alteração de equilíbrio e coordenação.", "explicacao": "Classificação funcional pelo GMFCS."}, {"id": 2000002966, "trilha": "saude", "materia": "fisio", "assunto": "Neurologia", "tipo": "pergunta", "frente": "O que é a síndrome de Guillain-Barré?", "verso": "Polirradiculoneuropatia aguda autoimune, com fraqueza ascendente e arreflexia, muitas vezes após infecção.", "explicacao": "Risco de insuficiência respiratória."}, {"id": 2000002967, "trilha": "saude", "materia": "fisio", "assunto": "Neurologia", "tipo": "pergunta", "frente": "Qual o objetivo da fisioterapia na doença de Parkinson?", "verso": "Melhorar a marcha, o equilíbrio, a amplitude de movimento e prevenir quedas, usando pistas visuais e auditivas.", "explicacao": ""}, {"id": 2000002968, "trilha": "saude", "materia": "fisio", "assunto": "Neurologia", "tipo": "pergunta", "frente": "O que é disreflexia autonômica?", "verso": "Crise hipertensiva em pacientes com lesão medular acima de T6, desencadeada por estímulo abaixo da lesão (bexiga cheia, por exemplo).", "explicacao": "Emergência: sentar o paciente e remover o estímulo."}, {"id": 2000002969, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pergunta", "frente": "Quais os volumes e capacidades pulmonares principais?", "verso": "Volume corrente, volume de reserva inspiratório e expiratório, volume residual, capacidade vital, capacidade residual funcional e capacidade pulmonar total.", "explicacao": ""}, {"id": 2000002970, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pares", "frente": "Distúrbio ventilatório obstrutivo x restritivo.", "verso": "Obstrutivo: redução do fluxo (VEF1/CVF baixo), como asma e DPOC. Restritivo: redução dos volumes pulmonares (CPT baixa), como fibrose e doenças neuromusculares.", "explicacao": ""}, {"id": 2000002971, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pergunta", "frente": "Para que serve a técnica de expiração forçada (huffing)?", "verso": "Deslocar secreções das vias aéreas periféricas para as centrais com menor colapso brônquico.", "explicacao": ""}, {"id": 2000002972, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pergunta", "frente": "Para que serve a drenagem postural?", "verso": "Usar a gravidade para mobilizar secreções de segmentos pulmonares específicos.", "explicacao": ""}, {"id": 2000002973, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pergunta", "frente": "Para que serve a pressão expiratória positiva (EPAP, PEP)?", "verso": "Manter as vias aéreas abertas, melhorar a ventilação colateral e ajudar na remoção de secreções.", "explicacao": "Ex.: flutter, shaker."}, {"id": 2000002974, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pergunta", "frente": "Para que serve o inspirômetro de incentivo?", "verso": "Estimular inspirações profundas e sustentadas, prevenindo atelectasias no pós-operatório.", "explicacao": ""}, {"id": 2000002975, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pergunta", "frente": "Quais os principais modos de ventilação mecânica invasiva?", "verso": "Volume controlado, pressão controlada e pressão de suporte (espontâneo), além de modos assistidos-controlados.", "explicacao": ""}, {"id": 2000002976, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pergunta", "frente": "Qual o volume corrente protetor na ventilação mecânica da SDRA?", "verso": "6 mL/kg do peso predito, com pressão de platô até 30 cmH₂O.", "explicacao": "Ventilação protetora."}, {"id": 2000002977, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pergunta", "frente": "O que é PEEP?", "verso": "Pressão positiva ao final da expiração, que mantém os alvéolos abertos e melhora a oxigenação.", "explicacao": ""}, {"id": 2000002978, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pergunta", "frente": "O que é o teste de respiração espontânea?", "verso": "Avaliação da capacidade de respirar sem suporte ventilatório pleno (tubo T ou pressão de suporte baixa) por 30 a 120 minutos, antes da extubação.", "explicacao": "Desmame ventilatório."}, {"id": 2000002979, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pergunta", "frente": "O que é o índice de Tobin?", "verso": "Relação entre frequência respiratória e volume corrente (em litros); valores abaixo de 105 sugerem sucesso no desmame.", "explicacao": "Índice de respiração rápida e superficial."}, {"id": 2000002980, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pergunta", "frente": "Quais as indicações de ventilação não invasiva?", "verso": "Exacerbação de DPOC com acidose respiratória, edema agudo de pulmão cardiogênico e pós-extubação em pacientes de risco, entre outras.", "explicacao": "Contraindicada em rebaixamento de consciência e instabilidade grave."}, {"id": 2000002981, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pares", "frente": "CPAP x BiPAP.", "verso": "CPAP: pressão contínua única nas vias aéreas. BiPAP: dois níveis de pressão, inspiratório (IPAP) e expiratório (EPAP).", "explicacao": ""}, {"id": 2000002982, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pergunta", "frente": "Por que a posição prona é usada na SDRA grave?", "verso": "Melhora a relação ventilação-perfusão e a oxigenação, recrutando regiões pulmonares dorsais.", "explicacao": "Por pelo menos 16 horas por dia."}, {"id": 2000002983, "trilha": "saude", "materia": "fisio", "assunto": "Cardiovascular", "tipo": "pergunta", "frente": "Quais as fases da reabilitação cardíaca?", "verso": "Fase I: hospitalar. Fase II: ambulatorial supervisionada logo após a alta. Fase III: ambulatorial de manutenção. Fase IV: programa de longo prazo, sem supervisão.", "explicacao": ""}, {"id": 2000002984, "trilha": "saude", "materia": "fisio", "assunto": "Cardiovascular", "tipo": "pergunta", "frente": "Como se calcula a frequência cardíaca máxima estimada?", "verso": "220 − idade.", "explicacao": "Fórmula simples; há outras mais precisas."}, {"id": 2000002985, "trilha": "saude", "materia": "fisio", "assunto": "Cardiovascular", "tipo": "pergunta", "frente": "Qual escala avalia a percepção subjetiva de esforço?", "verso": "Escala de Borg.", "explicacao": "Original de 6 a 20 ou modificada de 0 a 10."}, {"id": 2000002986, "trilha": "saude", "materia": "fisio", "assunto": "Recursos", "tipo": "pares", "frente": "Termoterapia por adição x subtração.", "verso": "Adição: calor (bolsa quente, infravermelho, ultrassom contínuo, ondas curtas). Subtração: frio (crioterapia).", "explicacao": "O calor aumenta o fluxo sanguíneo e a extensibilidade dos tecidos."}, {"id": 2000002987, "trilha": "saude", "materia": "fisio", "assunto": "Recursos", "tipo": "pergunta", "frente": "Quais as contraindicações gerais do calor terapêutico?", "verso": "Inflamação aguda, hemorragia, alteração de sensibilidade, neoplasia no local, insuficiência vascular e áreas com trombose.", "explicacao": ""}, {"id": 2000002988, "trilha": "saude", "materia": "fisio", "assunto": "Recursos", "tipo": "pares", "frente": "Ultrassom contínuo x pulsado.", "verso": "Contínuo: efeito térmico. Pulsado: efeito predominantemente não térmico (mecânico), útil em processos inflamatórios.", "explicacao": ""}, {"id": 2000002989, "trilha": "saude", "materia": "fisio", "assunto": "Recursos", "tipo": "pergunta", "frente": "Para que serve o TENS?", "verso": "Estimulação elétrica nervosa transcutânea para analgesia (teoria das comportas e liberação de opioides endógenos).", "explicacao": "Contraindicado sobre marca-passo e seio carotídeo."}, {"id": 2000002990, "trilha": "saude", "materia": "fisio", "assunto": "Recursos", "tipo": "pergunta", "frente": "Para que serve a FES?", "verso": "Estimulação elétrica funcional, que provoca contração muscular para fins funcionais, como marcha e preensão em pacientes neurológicos.", "explicacao": ""}, {"id": 2000002991, "trilha": "saude", "materia": "fisio", "assunto": "Recursos", "tipo": "pergunta", "frente": "Para que serve o laser de baixa potência?", "verso": "Modulação da inflamação, analgesia e reparo tecidual (fotobiomodulação).", "explicacao": "Proteção ocular obrigatória."}, {"id": 2000002992, "trilha": "saude", "materia": "fisio", "assunto": "Recursos", "tipo": "pergunta", "frente": "O que é a hidroterapia e quais suas vantagens?", "verso": "Exercícios na água aquecida, que reduz o peso corporal (empuxo), facilita os movimentos e relaxa a musculatura.", "explicacao": "Método Halliwick e Bad Ragaz."}, {"id": 2000002993, "trilha": "saude", "materia": "fisio", "assunto": "Saúde da mulher", "tipo": "pergunta", "frente": "Para que servem os exercícios de Kegel?", "verso": "Fortalecer a musculatura do assoalho pélvico, prevenindo e tratando incontinência urinária.", "explicacao": ""}, {"id": 2000002994, "trilha": "saude", "materia": "fisio", "assunto": "Saúde da mulher", "tipo": "pergunta", "frente": "Qual a fisioterapia indicada após mastectomia com esvaziamento axilar?", "verso": "Exercícios de amplitude de movimento do ombro, drenagem linfática e orientações para prevenir linfedema.", "explicacao": "Evitar punções e aferir pressão no membro homolateral."}, {"id": 2000002995, "trilha": "saude", "materia": "fisio", "assunto": "Pediatria", "tipo": "pergunta", "frente": "O que são reflexos primitivos e por que importam?", "verso": "Reflexos presentes nos primeiros meses (Moro, preensão palmar, sucção) que desaparecem com o amadurecimento; persistência pode indicar lesão neurológica.", "explicacao": ""}, {"id": 2000002996, "trilha": "saude", "materia": "fisio", "assunto": "Pediatria", "tipo": "pergunta", "frente": "Até que idade costuma desaparecer o reflexo de Moro?", "verso": "Em torno de 4 a 6 meses.", "explicacao": ""}, {"id": 2000002997, "trilha": "saude", "materia": "fisio", "assunto": "Geriatria", "tipo": "pergunta", "frente": "Qual intervenção mais reduz o risco de quedas em idosos?", "verso": "Exercícios de equilíbrio e fortalecimento muscular, associados à adequação do ambiente.", "explicacao": ""}, {"id": 2000002998, "trilha": "saude", "materia": "fisio", "assunto": "Geriatria", "tipo": "pergunta", "frente": "O que é sarcopenia?", "verso": "Perda progressiva de massa, força e desempenho muscular com o envelhecimento.", "explicacao": "Exercício resistido é o principal tratamento."}, {"id": 2000002999, "trilha": "saude", "materia": "fisio", "assunto": "Trabalho", "tipo": "pergunta", "frente": "Qual norma regulamentadora trata de ergonomia?", "verso": "NR 17.", "explicacao": "Adapta as condições de trabalho às características psicofisiológicas dos trabalhadores."}, {"id": 2000003000, "trilha": "saude", "materia": "fisio", "assunto": "Trabalho", "tipo": "pergunta", "frente": "O que são LER/DORT?", "verso": "Lesões por esforço repetitivo ou distúrbios osteomusculares relacionados ao trabalho, como tendinites e síndrome do túnel do carpo.", "explicacao": ""}]$c$::jsonb) as x(id integer, trilha text, materia text, assunto text, tipo text, frente text, verso text, explicacao text)
on conflict (id) do update set trilha = excluded.trilha, materia = excluded.materia, assunto = excluded.assunto, tipo = excluded.tipo,
  frente = excluded.frente, verso = excluded.verso, explicacao = excluded.explicacao, ativa = true, atualizado_em = now();

select trilha, count(*) as cartoes, public.cartoes_versao() as versao from public.cartoes where ativa group by trilha;
